head.script:
//
(function(){
var K='3d|id|projetos|designer-pleno|fotos|producao|perfil|portfolio|galeria|apps|blog';
var RX=new RegExp('^/('+K+')(?:/([^/?#]+))?/?$','i');
var SEC_ALIAS={about:'perfil',home:''};
function dec(x){try{return decodeURIComponent(x);}catch(e){return x;}}
function base(){
var m=location.pathname.match(RX);
if(m)return '/'+m[1].toLowerCase();
var oc=window.__opCur;if(oc){if(SEC_ALIAS.hasOwnProperty(oc))oc=SEC_ALIAS[oc];return oc?'/'+oc:'';}
var b=document.body,pg=b&&b.getAttribute&&b.getAttribute('data-spa-page');
if(pg)return '/'+pg;
var v=document.querySelectorAll('.flpnr_tm_section');
for(var i=0;i<v.length;i++){
var c=v[i].classList;
if(!c.contains('hidden')&&(c.contains('active')||c.contains('animated'))){
var id=v[i].id;
if(SEC_ALIAS.hasOwnProperty(id))id=SEC_ALIAS[id];
return id?'/'+id:'';
}
}
return '';
}
function slug(){
var m=location.pathname.match(RX);
if(m&&m[2])return dec(m[2]);
var h=location.hash;
if(h.length>1){
var parts=h.slice(1).split('/'),sl=dec(parts[parts.length-1]||'');
if(!sl)return '';
var el=document.getElementById(sl);
if(el&&el.classList&&el.classList.contains('flpnr_tm_section'))return '';
if(!el){
var b=base();
if(b){try{history.replaceState(history.state,'',b+'/'+encodeURIComponent(sl)+location.search);}catch(e){}}
}
return sl;
}
return '';
}
function url(sl){var b=base();return b?b+'/'+encodeURIComponent(sl)+location.search:'#'+sl;}
function closeUrl(){return (base()||location.pathname)+location.search;}
window.__fnrRoute={base:base,slug:slug,url:url,closeUrl:closeUrl,current:function(){return location.pathname+location.search;}};
})();
//

b:if.script:
//
(function(){var d=document.documentElement;d.classList.add('op-on');var p=(location.pathname||'/').replace(/^\/+|\/+$/g,'').split('/')[0];var s2={'projetos':1,'id':1,'3d':1,'designer-pleno':1,'fotos':1,'producao':1};d.classList.add(s2[p]?'op-s2':'op-s1');})();
//

head.b:skin:
/*
<Group description="Theme Color">
<Variable name="bar" description="Address bar color" type="color" default="#ffffff" value="#ffffff"/>
</Group>

<Group description="(Do not edit) New Blogger comment required">
<Variable name="body.background" description="Background" color="#1f1f1f" type="background" default="$(color) none repeat scroll center center"  value="$(color) url() no-repeat scroll center center"/>
<Variable name="body.text.font" description="Font Blogger comment" type="font" default="Roboto, sans-serif" value="400 12px Roboto, sans-serif"/>
<Variable name="body.text.color" description="Color" type="color" default="#ffffff"  value="#ffffff"/>
<Variable name="body.link.color" description="Link color" type="color" default="#262d3d"  value="#989b9f"/>
<Variable name="posts.title.color" description="Post title color" type="color" default="#262d3d"  value="#989b9f"/>
<Variable name="posts.text.color" description="Post text color" type="color" default="#48525c"  value="#989b9f"/>
<Variable name="posts.icons.color" description="Post info color" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="posts.background.color" description="Post background color" type="color" default="#f7f7fc"  value="transparent"/>
<Variable name="tabs.font" description="Font" type="font" default="Roboto, sans-serif" value="400 12px Roboto, sans-serif"/>
<Variable name="tabs.color" description="Text color" type="color" default="#fff"  value="#ffffff"/>
<Variable name="tabs.selected.color" description="Selected color" type="color" default="#fff"  value="#ffffff"/>
<Variable name="tabs.overflow.background.color" description="Popup background color" type="color" default="$(posts.background.color)"  value="#494b50"/>
<Variable name="tabs.overflow.color" description="Popup text color" type="color" default="#48525c"  value="#48525c"/>
<Variable name="tabs.overflow.selected.color" description="Popup selected color" type="color" default="#262d3d"  value="#989b9f"/>
<Variable name="labels.background.color" description="Labels background color" type="color" default="#494b50" value="#494b50"/>
<Variable name="blog.title.font" description="Blog title font" type="font" default="Roboto, sans-serif" value="400 12px Roboto, sans-serif"/>
<Variable name="blog.title.color" description="Blog title color" type="color" default="#fff" value="#ffffff"/>
</Group> 
 */
/* INDICE
   1. VARIAVEIS GLOBAIS
   2. RESET E ELEMENTOS BASE
   3. COMENTARIOS DO BLOGGER
   4. BIBLIOTECA: MAGNIFIC POPUP
   5. BIBLIOTECAS: ANIMATE E OWL CAROUSEL
   6. BIBLIOTECA: ICONE HAMBURGER
   7. BASE: SCROLLBAR, PLACEHOLDER, CONTAINER E TIPOGRAFIA
   8. LAYOUT DO TEMA
   9. LAYOUT DO TEMA: RESPONSIVO
   10. PLACEHOLDERS DE FORMULARIO E PRELOADER
   11. TEMA ESCURO (body.dark)
   12. FUNDO DA HOME E CARTOES DE VIDRO
   13. TITULOS DE SECAO, FATOS E SETAS
   14. PERFIL: FOTO, ORBITA, DICA DE TOQUE E REDES
   15. HOME: CAMADAS DE PARALLAX
   16. AUDIO: ALTO-FALANTE, CURSOR E BOTAO FLUTUANTE
   17. SECOES, BARRAS DE ROLAGEM E COLUNAS
   18. PAINEIS, CARTOES E MOLDURAS
   19. TITULOS DIGITADOS, GALERIAS E VIDEOS
   20. MODO LEVE
   21. AJUSTES DE MODAIS, CONTEUDO, BOTOES E DICAS
   22. GALERIA OPENSEA
   23. MENU DE PAGINAS (SPA) E LOADER
   24. IMAGENS SOB DEMANDA (SPA)
   25. STORIES DO PERFIL
   26. POP-UPS DE PROJETOS E IDENTIDADES
   27. CABECALHO DO CELULAR
   28. ONE-PAGE: SECOES
   29. REGUA DE ROLAGEM, MENU FLUTUANTE E LINHA DO TEMPO
   30. ONE-PAGE: AJUSTES POR SECAO
   31. INTERESSES E CARTOES DO SOBRE
   32. PAGINAS PROJETOS E IDENTIDADES: GALERIAS E MODAIS
   33. BOTOES FLUTUANTES E PERFORMANCE NO TOUCH
   34. PLACEHOLDERS, BOTOES PILULA E EFEITO DIFFERENCE
   35. ANIMACOES (KEYFRAMES)
   36. TABLET
*/
/* ========================================================================
   1. VARIAVEIS GLOBAIS
   ======================================================================== */
:root {
  --fnr-dots: url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 width=%276%27 height=%276%27%3E%3Ccircle cx=%27.9%27 cy=%27.7%27 r=%27.85%27 fill=%27white%27 fill-opacity=%27.17%27/%3E%3C/svg%3E");
}
html {
  --fnr-g-s: 8px;
  --fnr-g-m: 16px;
  --fnr-g-l: 24px;
  --fnr-sp-block: 32px;
  --fnr-sp-band: 48px;
  --fnr-sp-end: 16px;
  --fnr-card-v: 24px;
  --fnr-card-h: 20px;
}
/* ========================================================================
   2. RESET E ELEMENTOS BASE
   normalize, formularios, links, imagens
   ======================================================================== */
html {
  font-family: sans-serif;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}
a,
button,
[role=button],
label,
summary {
  -webkit-tap-highlight-color: transparent;
}
textarea,
input[type=text],
input[type=email],
input[type=search],
input[type=url],
input[type=tel],
input[type=password],
input[type=number],
input[type=submit] {
  -webkit-appearance: none;
  appearance: none;
}
body {
  margin: 0;
}
article,
aside,
details,
figcaption,
figure,
footer,
header,
hgroup,
main,
nav,
section,
summary {
  display: block;
}
audio,
canvas,
progress,
video {
  display: inline-block;
  vertical-align: baseline;
}
audio:not([controls]) {
  display: none;
  height: 0;
}
[hidden],
template {
  display: none;
}
a {
  background: transparent;
}
a:active,
a:hover {
  outline: 0;
}
abbr[title] {
  border-bottom: 1px dotted;
}
b,
strong {
  font-weight: bold;
}
dfn {
  font-style: italic;
}
h1 {
  font-size: 2em;
  margin: .67em 0;
}
mark {
  background: #ff0;
  color: #000;
}
small {
  font-size: 80%;
}
sub,
sup {
  font-size: 75%;
  line-height: 0;
  position: relative;
  vertical-align: baseline;
}
sup {
  top: -0.5em;
}
sub {
  bottom: -0.25em;
}
img {
  border: 0;
}
figure {
  margin: 1em 40px;
}
hr {
  box-sizing: content-box;
  height: 0;
}
pre {
  overflow: auto;
}
code,
kbd,
pre,
samp {
  font-family: monospace,monospace;
  font-size: 1em;
}
button,
input,
optgroup,
select,
textarea {
  color: inherit;
  font: inherit;
  margin: 0;
}
button {
  overflow: visible;
}
button,
select {
  text-transform: none;
}
button,
html input[type="button"],
input[type="reset"],
input[type="submit"] {
  -webkit-appearance: button;
  cursor: pointer;
}
button[disabled],
html input[disabled] {
  cursor: default;
}
button::-moz-focus-inner,
input::-moz-focus-inner {
  border: 0;
  padding: 0;
}
input {
  line-height: normal;
}
input[type="checkbox"],
input[type="radio"] {
  box-sizing: border-box;
  padding: 0;
}
input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  height: auto;
}
input[type="search"] {
  -webkit-appearance: textfield;
  box-sizing: content-box;
}
input[type="search"]::-webkit-search-cancel-button,
input[type="search"]::-webkit-search-decoration {
  -webkit-appearance: none;
}
fieldset {
  border: 2px solid #eee;
  margin: 0 2px;
  padding: .35em .625em .75em;
}
legend {
  border: 0;
  padding: 0;
}
textarea {
  overflow: auto;
}
optgroup {
  font-weight: bold;
}
table {
  border-collapse: collapse;
  border-spacing: 0;
}
td,
th {
  padding: 0;
}
html,
body,
div,
span,
applet,
object,
iframe,
h1,
h2,
h3,
h4,
h5,
h6,
p,
pre,
a,
abbr,
acronym,
address,
big,
code,
del,
dfn,
em,
font,
ins,
kbd,
s,
samp,
small,
strike,
strong,
sub,
sup,
tt,
var,
b,
u,
i,
center,
dl,
dt,
dd,
ol,
ul,
li,
fieldset,
form,
label,
legend,
table,
caption,
tbody,
tfoot,
thead,
tr,
th,
td {
  background: transparent;
  border: 0;
  margin: 0;
  padding: 0;
  vertical-align: baseline;
  outline: 0;
}
article,
aside,
details,
figcaption,
figure,
footer,
header,
hgroup,
nav,
section {
  display: block;
}
ul,
ol {
  margin: 0;
}
ul li,
ol li {
  margin: 0;
}
img {
  vertical-align: middle;
  max-width: 100%;
}
iframe {
  max-width: 100%;
}
del {
  text-decoration: line-through;
}
a,
i {
  border: 0;
}
a:hover {
  text-decoration: none;
}
textarea {
  border-radius: 0;
  font-size: 15px;
  resize: vertical;
  font-family: "JetBrains Mono";
  -webkit-font-smoothing: none;
  -moz-osx-font-smoothing: grayscale;
  font-smooth: never;
  text-rendering: optimizeSpeed;
  letter-spacing: 0 !important;
  box-sizing: border-box;
  line-height: 1.4;
  padding: 10px !important;
  width: 100%;
  border: 2px solid #eee;
  transition: all .3s ease;
}
input[type="text"],
input[type="password"],
input[type="datetime"],
input[type="datetime-local"],
input[type="date"],
input[type="month"],
input[type="time"],
input[type="week"],
input[type="number"],
input[type="email"],
input[type="url"],
input[type="search"],
input[type="tel"],
input[type="color"] {
  border-radius: 0;
  font-size: 15px;
  min-width: auto;
  letter-spacing: 0 !important;
  box-sizing: border-box;
  font-family: "JetBrains Mono";
  line-height: 1.6;
  padding: 10px !important;
  height: 44px;
  vertical-align: middle;
  border: 2px solid #eee;
  transition: all .3s ease;
}
textarea:focus,
input[type="text"]:focus,
input[type="password"]:focus,
input[type="datetime"]:focus,
input[type="datetime-local"]:focus,
input[type="date"]:focus,
input[type="month"]:focus,
input[type="time"]:focus,
input[type="week"]:focus,
input[type="number"]:focus,
input[type="email"]:focus,
input[type="url"]:focus,
input[type="search"]:focus,
input[type="tel"]:focus,
input[type="color"]:focus {
  border-color: rgba(0,0,0,.2);
  background: #eee;
}
input[type="submit"] {
  padding: 13px 15px;
  height: 40px;
  line-height: 1;
  text-transform: uppercase;
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  letter-spacing: 0;
  border: 0;
  cursor: pointer;
  color: #FFF;
  background: #777;
  transition: all .3s ease;
}
select {
  padding: 8px;
  border: 2px solid #eee;
}
input[type="button"] {
  cursor: pointer;
  transition: all .3s ease;
}
/* ========================================================================
   3. COMENTARIOS DO BLOGGER
   ======================================================================== */
.blogComments .commentReply {
  display: none;
}
.Blog .comments iframe {
  width: 100%;
  max-width: 100%;
}
body.dark .blogComments {
  border-top: 2px solid #56585c;
}
.blogComments {
  border-top: 2px solid #eee;
  padding-top: 50px;
  margin-top: 30px;
  width: 100%;
  float: left;
  clear: both;
}
.blogComments h3.title {
  margin: 0;
  padding: 0;
  margin-bottom: 25px;
  font-size: 15px;
  font-weight: 700;
  text-transform: uppercase;
  position: relative;
}
body.dark .blogComments h3.title:before {
  background-color: #56585c;
}
.blogComments h3.title:before {
  position: absolute;
  content: "";
  width: 40px;
  height: 2px;
  background-color: #eee;
  left: 0;
  bottom: -7px;
  opacity: 1;
}
.blogComments ol#commentHolder,
.blogComments ul {
  margin: 0;
  padding: 0;
  list-style-type: none;
}
.blogComments .commentFlex {
  padding: 30px 30px 25px;
  background-color: #fff;
  box-shadow: 0 5px 10px rgb(0 0 0 / 5%);
  position: relative;
}
body.dark .blogComments .commentFlex {
  background-image: none;
  background-color: transparent;
}
.blogComments ol li {
  padding-top: 20px;
}
.blogComments .commentAvatar {
  position: relative;
  float: left;
  margin: 0 20px 20px 0;
  width: 80px;
  height: 80px;
  display: block;
  top: 0;
  left: 0;
}
.blogComments .commentAvatar img {
  border-radius: 50%;
}
.blogComments .commentHeader {
  min-height: 80px;
  padding: 0;
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.blogComments .commentHeader h3 {
  margin: 0;
  padding: 0;
  font-weight: 500;
  font-size: 15px;
  margin-bottom: 5px;
  text-transform: capitalize;
  line-height: 1;
}
.blogComments .commentDataTime {
  margin: 0;
  padding: 0;
  font-weight: 400;
  font-family: JetBrains Mono;
  font-size: 13px;
}
.blogComments .commentContent {
  font-size: 16px;
  line-height: 26px;
  margin-bottom: 33px;
  letter-spacing: 0;
}
.commentThread .threadToggle:after,
.commentActions a:after,
.commentReply a:after {
  content: attr(data-text);
}
.blogComments .commentReply1 {
  display: block;
  float: left;
  position: relative;
  margin: 0 5px 5px 0;
}
.blogComments .commentActions:after {
  clear: both;
  display: table;
  content: '';
}
body.dark .replaced-svg {
  color: #fff;
}
.replaced-svg {
  position: absolute;
  left: 10px;
  width: 12px;
  height: 12px;
  top: 50%;
  margin-top: -6px;
  color: #000;
  fill: currentColor;
}
.blogComments .commentReply1 a {
  padding-left: 29px;
  margin: 0;
  font-size: 13px;
  color: #000;
  text-decoration: none;
  line-height: 26px;
  padding-right: 10px;
  float: left;
  border: 0;
  background-color: #ddd;
  text-transform: capitalize;
  height: 26px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
body.dark .blogComments .commentReply1 a {
  background: #1f1f1f;
  color: #fff;
}
body.dark #threaded-comment-form {
  background-image: none;
  background-color: transparent;
}
#threaded-comment-form {
  padding: 23px 30px 30px;
  margin-top: 20px;
  background-color: #fff;
  box-shadow: 0 5px 10px rgb(0 0 0 / 5%);
}
/* ========================================================================
   4. BIBLIOTECA: MAGNIFIC POPUP
   lightbox de imagens/iframes
   ======================================================================== */
.mfp-bg,
.mfp-wrap {
  position: fixed;
  left: 0;
  top: 0;
}
.mfp-bg,
.mfp-container,
.mfp-wrap {
  height: 100%;
  width: 100%;
}
.mfp-arrow:after,
.mfp-arrow:before,
.mfp-container:before,
.mfp-figure:after {
  content: '';
}
.mfp-bg {
  z-index: 1042;
  overflow: hidden;
  background: #0b0b0b;
  opacity: .8;
}
.mfp-wrap {
  z-index: 1043;
  outline: 0 !important;
  -webkit-backface-visibility: hidden;
}
.mfp-container {
  text-align: center;
  position: absolute;
  left: 0;
  top: 0;
  padding: 0 8px;
  box-sizing: border-box;
}
.mfp-container:before {
  display: inline-block;
  height: 100%;
  vertical-align: middle;
}
.mfp-align-top .mfp-container:before {
  display: none;
}
.mfp-content {
  position: relative;
  display: inline-block;
  vertical-align: middle;
  margin: 0 auto;
  text-align: left;
  z-index: 1045;
}
.mfp-ajax-holder .mfp-content,
.mfp-inline-holder .mfp-content {
  width: 100%;
  cursor: auto;
}
.mfp-ajax-cur {
  cursor: progress;
}
.mfp-zoom-out-cur,
.mfp-zoom-out-cur .mfp-image-holder .mfp-close {
  cursor: zoom-out;
}
.mfp-zoom {
  cursor: zoom-in;
}
.mfp-auto-cursor .mfp-content {
  cursor: auto;
}
.mfp-arrow,
.mfp-close,
.mfp-counter,
.mfp-preloader {
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
}
.mfp-loading.mfp-figure {
  display: none;
}
.mfp-hide {
  display: none !important;
}
.mfp-preloader {
  color: #CCC;
  position: absolute;
  top: 50%;
  width: auto;
  text-align: center;
  margin-top: -.8em;
  left: 8px;
  right: 8px;
  z-index: 1044;
}
.mfp-preloader a {
  color: #CCC;
}
.mfp-close,
.mfp-preloader a:hover {
  color: #FFF;
}
.mfp-s-error .mfp-content,
.mfp-s-ready .mfp-preloader {
  display: none;
}
button.mfp-arrow,
button.mfp-close {
  overflow: visible;
  cursor: pointer;
  background: 0;
  border: 0;
  -webkit-appearance: none;
  display: block;
  outline: 0;
  padding: 0;
  z-index: 1046;
  box-shadow: none;
  touch-action: manipulation;
}
.mfp-figure:after,
.mfp-iframe-scaler iframe {
  box-shadow: 0 0 8px rgba(0,0,0,.6);
  position: absolute;
  left: 0;
}
button::-moz-focus-inner {
  padding: 0;
  border: 0;
}
.mfp-close {
  width: 44px;
  height: 44px;
  line-height: 44px;
  position: absolute;
  right: 0;
  top: 0;
  text-decoration: none;
  text-align: center;
  opacity: .65;
  padding: 0 0 18px 10px;
  font-style: normal;
  font-size: 28px;
  font-family: Arial,Baskerville,monospace;
}
.mfp-close:focus,
.mfp-close:hover {
  opacity: 1;
}
.mfp-close:active {
  top: 1px;
}
.mfp-close-btn-in .mfp-close {
  color: #333;
}
.mfp-iframe-holder .mfp-close,
.mfp-image-holder .mfp-close {
  color: #FFF;
  right: -6px;
  text-align: right;
  padding-right: 6px;
  width: 100%;
}
.mfp-counter {
  position: absolute;
  top: 0;
  right: 0;
  color: #CCC;
  font-size: 12px;
  line-height: 18px;
  white-space: nowrap;
}
.mfp-figure,
img.mfp-img {
  line-height: 0;
}
.mfp-arrow {
  position: absolute;
  opacity: .65;
  margin: -55px 0 0;
  top: 50%;
  padding: 0;
  width: 90px;
  height: 110px;
  -webkit-tap-highlight-color: transparent;
}
.mfp-arrow:active {
  margin-top: -54px;
}
.mfp-arrow:focus,
.mfp-arrow:hover {
  opacity: 1;
}
.mfp-arrow:after,
.mfp-arrow:before {
  display: block;
  width: 0;
  height: 0;
  position: absolute;
  left: 0;
  top: 0;
  margin-top: 35px;
  margin-left: 35px;
  border: inset transparent;
}
.mfp-arrow:after {
  border-top-width: 13px;
  border-bottom-width: 13px;
  top: 8px;
}
.mfp-arrow:before {
  border-top-width: 21px;
  border-bottom-width: 21px;
  opacity: .7;
}
.mfp-arrow-left {
  left: 0;
}
.mfp-arrow-left:after {
  border-right: 17px solid #FFF;
  margin-left: 31px;
}
.mfp-arrow-left:before {
  margin-left: 25px;
  border-right: 27px solid #3f3f3f;
}
.mfp-arrow-right {
  right: 0;
}
.mfp-arrow-right:after {
  border-left: 17px solid #FFF;
  margin-left: 39px;
}
.mfp-arrow-right:before {
  border-left: 27px solid #3f3f3f;
}
.mfp-iframe-holder {
  padding-top: 40px;
  padding-bottom: 40px;
}
.mfp-iframe-holder .mfp-content {
  line-height: 0;
  width: 100%;
  max-width: 900px;
}
.mfp-image-holder .mfp-content,
img.mfp-img {
  max-width: 100%;
}
.mfp-iframe-holder .mfp-close {
  top: -40px;
}
.mfp-iframe-scaler {
  width: 100%;
  height: 0;
  overflow: hidden;
  padding-top: 56.25%;
}
.mfp-iframe-scaler iframe {
  display: block;
  top: 0;
  width: 100%;
  height: 100%;
  background: #000;
}
.mfp-figure:after,
img.mfp-img {
  width: auto;
  height: auto;
  display: block;
}
img.mfp-img {
  box-sizing: border-box;
  padding: 40px 0;
  margin: 0 auto;
}
.mfp-figure:after {
  top: 40px;
  bottom: 40px;
  right: 0;
  z-index: -1;
  background: #444;
}
.mfp-figure small {
  color: #bdbdbd;
  display: block;
  font-size: 12px;
  line-height: 14px;
}
.mfp-figure figure {
  margin: 0;
}
.mfp-bottom-bar {
  margin-top: -36px;
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  cursor: auto;
}
.mfp-title {
  text-align: left;
  line-height: 18px;
  color: #f3f3f3;
  word-wrap: break-word;
  padding-right: 36px;
}
.mfp-gallery .mfp-image-holder .mfp-figure {
  cursor: pointer;
}
@media screen and (max-width:800px) and (orientation:landscape),screen and (max-height:300px) {
  .mfp-img-mobile .mfp-image-holder {
    padding-left: 0;
    padding-right: 0;
  }
  .mfp-img-mobile img.mfp-img {
    padding: 0;
  }
  .mfp-img-mobile .mfp-figure:after {
    top: 0;
    bottom: 0;
  }
  .mfp-img-mobile .mfp-figure small {
    display: inline;
    margin-left: 5px;
  }
  .mfp-img-mobile .mfp-bottom-bar {
    background: rgba(0,0,0,.6);
    bottom: 0;
    margin: 0;
    top: auto;
    padding: 3px 5px;
    position: fixed;
    box-sizing: border-box;
  }
  .mfp-img-mobile .mfp-bottom-bar:empty {
    padding: 0;
  }
  .mfp-img-mobile .mfp-counter {
    right: 5px;
    top: 3px;
  }
  .mfp-img-mobile .mfp-close {
    top: 0;
    right: 0;
    width: 35px;
    height: 35px;
    line-height: 35px;
    background: rgba(0,0,0,.6);
    position: fixed;
    text-align: center;
    padding: 0;
  }
}
@media all and (max-width:900px) {
  .mfp-arrow {
    -webkit-transform: scale(.75);
    transform: scale(.75);
  }
  .mfp-arrow-left {
    -webkit-transform-origin: 0 0;
    transform-origin: 0 0;
  }
  .mfp-arrow-right {
    -webkit-transform-origin: 100%;
    transform-origin: 100%;
  }
  .mfp-container {
    padding-left: 6px;
    padding-right: 6px;
  }
}
/* ========================================================================
   5. BIBLIOTECAS: ANIMATE E OWL CAROUSEL
   ======================================================================== */
.animated {
  animation-duration: 1s;
  animation-fill-mode: both;
}
.fadeInUp {
  animation-name: fadeInUp;
}
.owl-carousel,
.owl-carousel .owl-item {
  -webkit-tap-highlight-color: transparent;
  position: relative;
}
.owl-carousel {
  display: none;
  width: 100%;
  z-index: 1;
}
.owl-carousel .owl-stage {
  position: relative;
  -ms-touch-action: pan-Y;
  -moz-backface-visibility: hidden;
}
.owl-carousel .owl-stage:after {
  content: ".";
  display: block;
  clear: both;
  visibility: hidden;
  line-height: 0;
  height: 0;
}
.owl-carousel .owl-stage-outer {
  position: relative;
  overflow: hidden;
  -webkit-transform: translate3d(0,0,0);
}
.owl-carousel .owl-item,
.owl-carousel .owl-wrapper {
  -webkit-backface-visibility: hidden;
  -webkit-transform: translate3d(0,0,0);
  -ms-transform: translate3d(0,0,0);
}
.owl-carousel .owl-item {
  min-height: 1px;
  float: left;
  -webkit-backface-visibility: hidden;
  -webkit-touch-callout: none;
}
.owl-carousel .owl-item img {
  width: auto;
}
.owl-carousel .owl-dots.disabled,
.owl-carousel .owl-nav.disabled {
  display: none;
}
.no-js .owl-carousel,
.owl-carousel.owl-loaded {
  display: block;
}
.owl-carousel .owl-dot,
.owl-carousel .owl-nav .owl-next,
.owl-carousel .owl-nav .owl-prev {
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
}
.owl-carousel.owl-loading {
  opacity: 0;
  display: block;
}
.owl-carousel.owl-hidden {
  opacity: 0;
}
.owl-carousel.owl-refresh .owl-item {
  visibility: hidden;
}
.owl-carousel.owl-drag .owl-item {
  -webkit-user-select: none;
  user-select: none;
}
.owl-carousel.owl-grab {
  cursor: move;
  cursor: grab;
}
.owl-carousel.owl-rtl {
  direction: rtl;
}
.owl-carousel.owl-rtl .owl-item {
  float: right;
}
.owl-carousel .animated {
  animation-duration: 1s;
  animation-fill-mode: both;
}
.owl-carousel .owl-animated-in {
  z-index: 0;
}
.owl-carousel .owl-animated-out {
  z-index: 1;
}
.owl-carousel .owl-item img.owl-lazy {
  transform-style: preserve-3d;
}
/* ========================================================================
   6. BIBLIOTECA: ICONE HAMBURGER
   ======================================================================== */
.hamburger {
  font: inherit;
  display: inline-block;
  overflow: visible;
  margin: 0;
  padding: 15px;
  cursor: pointer;
  transition-timing-function: linear;
  transition-duration: .15s;
  transition-property: opacity,filter;
  text-transform: none;
  color: inherit;
  border: 0;
  background-color: transparent;
}
.hamburger.is-active:hover,
.hamburger:hover {
  opacity: 1;
}
.hamburger.is-active .hamburger-inner,
.hamburger.is-active .hamburger-inner:after,
.hamburger.is-active .hamburger-inner:before {
  background-color: #000;
}
.hamburger-box {
  position: relative;
  display: inline-block;
  width: 40px;
  height: 24px;
}
.hamburger-inner {
  top: 50%;
  display: block;
  margin-top: -2px;
}
.hamburger-inner,
.hamburger-inner:after,
.hamburger-inner:before {
  position: absolute;
  width: 40px;
  height: 4px;
  transition-timing-function: ease;
  transition-duration: .15s;
  transition-property: transform;
  border-radius: 4px;
  background-color: #000;
}
.hamburger-inner:after,
.hamburger-inner:before {
  display: block;
  content: "";
}
.hamburger-inner:before {
  top: -10px;
}
.hamburger-inner:after {
  bottom: -10px;
}
.hamburger--slider .hamburger-inner {
  top: 2px;
}
.hamburger--slider .hamburger-inner:after {
  top: 20px;
}
.hamburger--slider.is-active .hamburger-inner {
  transform: translate3d(0,10px,0) rotate(45deg);
}
.hamburger--slider.is-active .hamburger-inner:before {
  transform: rotate(-45deg) translate3d(-5.71429px,-6px,0);
  opacity: 0;
}
.hamburger--slider.is-active .hamburger-inner:after {
  transform: translate3d(0,-20px,0) rotate(-90deg);
}
/* ========================================================================
   7. BASE: SCROLLBAR, PLACEHOLDER, CONTAINER E TIPOGRAFIA
   ======================================================================== */
html {
  overflow-x: hidden;
  padding: 0;
  margin: 0;
}
body {
