}
::placeholder {
  color: #6f6f6f;
}
.container {
  max-width: 1070px;
  width: 100%;
  margin-left: auto;
  margin-right: auto;
  height: auto;
  padding: 0 40px;
  position: relative;
  clear: both;
}
h1,
h2,
h3,
h4,
h5,
h6 {
