/* ========================================================================
   12. FUNDO DA HOME E CARTOES DE VIDRO
   ======================================================================== */
/* Vamos conversar?: video de cada cartao, atras do texto e da borda e na
   frente da imagem de fundo. Aparece a direita e some em degrade para a
   esquerda (e de leve em cima e embaixo). Cinza como em Interesses;
   colorido com o mouse sobre o cartao. No modo energia fica so o poster */
.flpnr_tm_pricing .fnr-pv {
  position: absolute;
  top: 27%;
  right: -5%;
  width: 52%;
  height: 51%;
  object-fit: cover;
  z-index: -1;
  pointer-events: none;
  background: transparent;
  filter: grayscale(1) contrast(1.15) brightness(.7);
  transition: filter .45s ease;
  -webkit-mask-image: linear-gradient(to left,#000 35%,transparent 100%), linear-gradient(to bottom,transparent 0,#000 16%,#000 84%,transparent 100%);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to left,#000 35%,transparent 100%), linear-gradient(to bottom,transparent 0,#000 16%,#000 84%,transparent 100%);
  mask-composite: intersect;
}
@media (hover:hover) {
  .flpnr_tm_pricing .list_inner:hover .fnr-pv {
    filter: none;
  }
}
@media (max-width:768px) {
  .flpnr_tm_pricing .fnr-pv {
    width: 50%;
    right: -3%;
  }
}
@media (prefers-reduced-motion:reduce) {
  .flpnr_tm_pricing .fnr-pv {
    transition: none;
  }
}
.bg-video {
  position: absolute;
  top: 50%;
  left: 50%;
  min-width: 100%;
  min-height: 100%;
  width: 50%;
  height: 50%;
  object-fit: contain;
  transform: translate(-50%, -50%);
  object-fit: cover;
  z-index: 1;
}
.content_overlay {
  position: relative;
  z-index: 2;
  text-align: center;
  color: #ffffff;
  background: rgba(0, 0, 0, 0.3);
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.glass-card {
  padding: 10px;
  border-radius: 15px;
  color: white;
  position: relative;
  overflow: hidden;
  transition: all 0.5s ease;
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.3);
}
.glass-card::before {
  content: "";
  position: absolute;
  top: -150%;
  left: -150%;
  width: 350%;
  height: 350%;
  background: linear-gradient( 135deg, rgba(255, 255, 255, 0) 0%, rgba(100, 200, 255, 0.2) 25%, rgba(255, 100, 255, 0.2) 50%, rgba(100, 255, 200, 0.2) 75%, rgba(255, 255, 255, 0) 100% );
  opacity: 0;
  transition: opacity 0.5s ease;
  pointer-events: none;
}
.glass-card:hover {
  transform: translateY(-5px);
  border: 1px solid rgba(255, 255, 255, 0.5);
  box-shadow: 0 12px 40px 0 rgba(0, 0, 0, 0.4);
}
.glass-card:hover::before {
  opacity: 1;
  animation: holoFlow 3s infinite linear;
}
