  right: -46px;
  transform: translateY(-50%);
  z-index: 10;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.12);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  text-decoration: none;
  transition: background .2s, border-color .2s, transform .3s ease;
  -webkit-tap-highlight-color: transparent;
}
.opensea-arrow svg {
  display: block;
  transition: transform .3s ease;
}
.opensea-arrow:hover,
.opensea-arrow:focus-visible {
  background: rgba(0,0,0,0.85);
  border-color: rgba(255,255,255,0.4);
  transform: translateY(-50%) scale(1.08);
  outline: none;
}
.opensea-arrow:hover svg,
.opensea-arrow:focus-visible svg {
  transform: translateX(2px);
}
body.dark .opensea-arrow:hover,
body.dark .opensea-arrow:focus-visible {
  background: rgba(255,255,255,0.25);
}
.flpnr_tm_facts .list .in-fact .widget {
  transition: transform .55s cubic-bezier(.22,1,.36,1);
}
.opensea-arrow:hover ~ .in-fact .widget,
.opensea-arrow:focus-visible ~ .in-fact .widget {
  transform: translateX(-14px);
}
.opensea-arrow:hover ~ .in-fact .widget:nth-child(2),
.opensea-arrow:focus-visible ~ .in-fact .widget:nth-child(2) {
  transition-delay: .04s;
}
.opensea-arrow:hover ~ .in-fact .widget:nth-child(3),
.opensea-arrow:focus-visible ~ .in-fact .widget:nth-child(3) {
  transition-delay: .08s;
}
.opensea-arrow:hover ~ .in-fact .widget:nth-child(4),
.opensea-arrow:focus-visible ~ .in-fact .widget:nth-child(4) {
  transition-delay: .12s;
}
.opensea-arrow:hover ~ .in-fact .widget:nth-child(5),
.opensea-arrow:focus-visible ~ .in-fact .widget:nth-child(5) {
  transition-delay: .16s;
}
.opensea-arrow:hover ~ .in-fact .widget:nth-child(6),
.opensea-arrow:focus-visible ~ .in-fact .widget:nth-child(6) {
  transition-delay: .20s;
}
@media (max-width:1040px) {
  .flpnr_tm_facts .list {
    padding-right: 0;
    display: flex;
    flex-direction: column;
  }
  .opensea-arrow {
    position: relative;
    top: auto;
    right: auto;
    order: 2;
    width: 38px;
    height: 38px;
    margin: 0 auto;
    transform: none;
  }
  .opensea-arrow svg {
    transform: none;
  }
  .opensea-arrow:hover,
  .opensea-arrow:focus-visible {
    transform: scale(1.08);
  }
  .opensea-arrow:hover svg,
  .opensea-arrow:focus-visible svg {
    transform: translateX(2px);
  }
  .opensea-arrow:hover ~ .in-fact .widget,
  .opensea-arrow:focus-visible ~ .in-fact .widget {
    transform: none;
  }
}
@media (prefers-reduced-motion:reduce) {
  .flpnr_tm_facts .list .in-fact .widget {
    transition: none;
  }
  .opensea-arrow:hover ~ .in-fact .widget,
  .opensea-arrow:focus-visible ~ .in-fact .widget {
    transform: none;
  }
}
html.fnr-lite .opensea-arrow:hover ~ .in-fact .widget,
html.fnr-lite .opensea-arrow:focus-visible ~ .in-fact .widget {
  transform: none;
}
#blog-pager,
.blog-pager {
  display: none !important;
}
.static_page .short {
  display: none !important;
}
#typed-text b {
  font-weight: 800 !important;
