/* ========================================================================
   14. PERFIL: FOTO, ORBITA, DICA DE TOQUE E REDES
   ======================================================================== */
.profile-container {
  position: relative;
  width: 200px;
  height: 200px;
  margin: 0 auto;
  overflow: visible;
  margin-bottom: 60px;
}
@media (min-width: 1041px) {
  .profile-container {
    margin-bottom: 0;
  }
}
.profile-container .avatar {
  min-width: 200px;
  min-height: 200px;
  width: 200px;
  height: 200px;
  position: relative;
}
.orbit-network-canvas {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 1;
  width: 480px;
  height: 480px;
  opacity: 0;
  transition: opacity 0.5s ease;
  display: inline-block;
}
.orbit-network-canvas.visible {
  opacity: 1;
}
.profile-pic-wrapper {
  position: relative;
  width: 200px;
  height: 200px;
  cursor: pointer;
  z-index: 10;
}
.profile-container .avatar {
  position: relative;
  z-index: 2;
}
.avatar[data-type="wave"] .image,
.avatar[data-type="circle"] .image {
  position: absolute;
  inset: 0;
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
  border-radius: 50%;
  transition: transform 0.3s ease;
  cursor: pointer;
  z-index: 10;
}
.profile-pic-wrapper::before {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 4px solid transparent;
  background: linear-gradient(#212121, #212121) padding-box, radial-gradient(circle at 15% 90%, #f9ed69 0%, #ff7a00 15%, transparent 60%) border-box, radial-gradient(circle at 85% 15%, #f1b8dd 0%, #e55ea3 35%, #b641b1 55%, #833ab4 75%, #868afd 100%) border-box;
  background-blend-mode: normal, screen;
  pointer-events: none;
  animation: stories-smooth-pulse 4s linear infinite;
}
.profile-pic-wrapper.menu-locked::before {
  animation: none;
  background: linear-gradient(#212121, #212121) padding-box, radial-gradient(circle at 15% 90%, #f9ed69 0%, #ff7a00 15%, transparent 60%) border-box, radial-gradient(circle at 85% 15%, #fff 0%, #fff 35%, #f1b8dd 55%, #f1b8dd 100%) border-box;
  background-blend-mode: normal, screen;
  opacity: 1;
}
.profile-pic-wrapper:hover .avatar .image {
  transform: scale(1.04);
  cursor: pointer;
  box-shadow: 0px 8px 15px rgba(255, 255, 255, 0.3);
}
.fnr-tap-hint {
  position: absolute;
  top: 75%;
  left: 45%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.75);
  pointer-events: none;
  animation: hint-float 2s ease-in-out infinite, hint-fadein 0.8s ease 1.2s both;
  z-index: 15;
  transition: opacity 0.4s ease;
  mix-blend-mode: hard-light;
}
.fnr-tap-hint.hidden,
html.fnr-lite .fnr-tap-hint.hidden {
  animation: hint-float 2s ease-in-out infinite, hint-fadeout 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.fnr-tap-hint.hidden svg {
  transition: opacity 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  opacity: 0;
}
@media (prefers-reduced-motion: reduce) {
  .fnr-tap-hint.hidden,
  html.fnr-lite .fnr-tap-hint.hidden {
    animation: hint-fadeout-simple 0.4s ease forwards;
  }
  @keyframes hint-fadeout-simple {
    from {
      opacity: 1;
    }
    to {
      opacity: 0;
    }
  }
}
.fnr-tap-hint svg {
  width: 22px;
  height: 22px;
  fill: rgba(255,255,255,0.55);
  flex-shrink: 0;
}
.profile-pic-wrapper.menu-locked .avatar .image {
  box-shadow: none;
}
.social-orbit-item {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  z-index: 20;
  pointer-events: none;
  opacity: 0;
  transform: translate(0px, 0px) scale(0.2);
  transition: opacity 0.45s cubic-bezier(0.34, 1.56, 0.64, 1), transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.social-orbit-item.visible {
  opacity: 1;
  pointer-events: all;
}
.social-orbit-item a {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  border-radius: 50% !important;
  box-shadow: inset 0 0 0 3px rgba(255,255,255,.3);
  text-decoration: none;
  transition: box-shadow 0.3s ease, transform 0.3s ease;
  position: relative;
  overflow: hidden;
}
.social-orbit-item a::before {
  content: '';
  border: 1px rgba(255,255,255,0.25) solid;
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: rgba(31,31,31,1);
  transition: background 0.3s ease;
  z-index: 1;
}
.social-orbit-item a:hover::before {
  background: rgba(81,81,81,1);
}
.social-orbit-item a svg {
  width: 22px;
  height: 22px;
  fill: #fff;
  position: relative;
  z-index: 2;
  filter: drop-shadow(0 1px 3px rgba(0,0,0,0.6));
  transition: transform 0.3s ease;
}
.social-orbit-item a:hover svg {
  transform: scale(1.2);
}
.social-orbit-item a:hover {
  box-shadow: inset 0 0 0 5px rgba(255,255,255,.7), 0 0 20px rgba(255,255,255,0.2);
}
/* ========================================================================
   15. HOME: CAMADAS DE PARALLAX
   ======================================================================== */
#home {
  position: relative;
}
.parallax-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: contain;
  pointer-events: none;
  will-change: transform;
  transform-origin: center center;
}
/* objetos flutuantes: imagem (repouso) e video (vivo) no mesmo quadro 16:9.
   object-fit: contain mantem a posicao igual para video 720p ou 1080p,
   desde que o enquadramento do objeto no quadro seja o mesmo */
.fnr-floater-body {
  position: absolute;
  inset: 0;
}
.fnr-floater-img,
.fnr-floater-vid {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  transform: translate(-50%, -50%);
  object-fit: contain;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
  transition: opacity .4s ease;
}
.fnr-floater-vid {
  opacity: 0;
}
.fnr-floater.is-live .fnr-floater-vid {
  opacity: 1;
}
.fnr-floater.is-live .fnr-floater-img {
  opacity: 0;
}
.parallax-layer-1 {
  z-index: -3;
  filter: contrast(0.85);
}
.parallax-layer-2 {
  z-index: -2;
  filter: contrast(0.85);
}
@media (max-width: 768px) {
  .parallax-layer-2 .fnr-floater-img,
  .parallax-layer-2 .fnr-floater-vid {
    width: 130%;
  }
}
.parallax-layer-3 {
  z-index: -1;
  filter: contrast(0.85);
}
#home {
  --fnr-exit: 0;
}
.parallax-layer {
  --exit-ty: -60px;
  --exit-sc: .12;
  translate: 0 calc(var(--fnr-exit, 0) * var(--exit-ty));
  scale: calc(1 + var(--fnr-exit, 0) * var(--exit-sc));
  opacity: calc(1 - (var(--fnr-exit, 0) - .15) / .65);
}
.parallax-layer-1 {
  --exit-ty: -70px;
  --exit-sc: .15;
}
.parallax-layer-2 {
  --exit-ty: -150px;
  --exit-sc: .32;
}
.parallax-layer-3 {
  --exit-ty: -260px;
  --exit-sc: .58;
}
@media (max-width: 768px) {
  .parallax-layer-1 {
    --exit-ty: -42px;
    --exit-sc: .09;
  }
  .parallax-layer-2 {
    --exit-ty: -90px;
    --exit-sc: .19;
  }
  .parallax-layer-3 {
    --exit-ty: -150px;
    --exit-sc: .35;
  }
}
html.fnr-lite .parallax-layer {
  translate: none;
  scale: none;
  opacity: 1;
}
@media (prefers-reduced-motion: reduce) {
  .parallax-layer {
    translate: none;
    scale: none;
    opacity: 1;
  }
}
/* 2a navegacao: um objeto por par de paginas (esquerda, direita, esquerda),
   atras do conteudo; o JS faz cada um subir pela tela com a rolagem */
#fnr-floaters2 {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  height: 100lvh;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
  --f2-w: clamp(480px, 60vw, 1120px);
  --f2-side: 450px;
}
html.op-on.op-s2 #fnr-floaters2 {
  display: block;
}
.fnr-f2 {
  position: absolute;
  top: 50%;
  width: var(--f2-w);
  aspect-ratio: 16 / 9;
  margin-top: calc(var(--f2-w) * -.28125);
  visibility: hidden;
  will-change: transform;
}
.fnr-f2.is-on {
  visibility: visible;
}
.fnr-f2.is-left {
  left: calc(var(--f2-side) - var(--f2-w) * .18);
}
.fnr-f2.is-right {
  right: calc(var(--f2-w) * -.18);
}
.fnr-f2 .fnr-floater-body {
  animation: fnrFloatBob 7s ease-in-out infinite;
}
.fnr-f2.is-right .fnr-floater-body {
  animation-duration: 8.5s;
  animation-direction: reverse;
}
@media (max-width:1600px) {
  #fnr-floaters2 {
    --f2-side: 350px;
  }
}
@media (max-width:1200px) {
  /* celular/tablet: sticky em vez de fixed, para a camada passar por tras
     da barra do Safari (o iOS corta camadas fixed na altura da barra) */
  #fnr-floaters2 {
    position: sticky;
    height: calc(100vh + 200px);
    height: calc(100lvh + 200px);
    margin-bottom: calc(-100vh - 200px);
    margin-bottom: calc(-100lvh - 200px);
    --f2-side: 0px;
    --f2-w: clamp(440px, 92vw, 1040px);
  }
  /* o conteudo do tema e flutuante (float); sem isto o body fica curto
     e a camada sticky para de acompanhar a rolagem no meio da pagina */
  html.op-on.op-s2 body {
    display: flow-root;
  }
}
@media (max-width:768px) {
  #fnr-floaters2 {
    --f2-w: 144vw;
  }
  .fnr-f2 {
    opacity: .6;
  }
}
html.fnr-lite .fnr-f2 .fnr-floater-body {
  animation: none;
}
@media (prefers-reduced-motion: reduce) {
  .fnr-f2 .fnr-floater-body {
    animation: none;
  }
}
