}
#home,
#home .details,
#home .flpnr_tm_home,
#home .home_content {
  -webkit-user-select: text !important;
  user-select: text !important;
  -webkit-touch-callout: default !important;
}
#fnr-sound-cursor {
  position: fixed;
  pointer-events: none;
  z-index: 99999;
  display: none;
  transform: translate(-50%, -50%);
}
#fnr-sound-cursor svg {
  filter: drop-shadow(0 2px 8px rgba(0,0,0,0.7));
  animation: fnr-pulse 1.4s ease-in-out infinite;
}
#fnr-sound-cursor.playing circle {
  fill: #868afd;
  fill-opacity: 0.95;
}
#fnr-sound-cursor.playing path {
