}
#fnr-sound-tooltip {
  position: fixed;
  pointer-events: none;
  z-index: 99998;
  display: none;
  background: rgba(20,20,30,0.85);
  color: #fff;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  padding: 4px 10px;
  border-radius: 20px;
  white-space: nowrap;
  letter-spacing: 0.05em;
  transform: translate(-50%, 28px);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(134,138,253,0.3);
  transition: opacity 0.2s ease;
}
#fnr-float-icon {
  position: fixed;
  top: auto;
  bottom: calc(74px + env(safe-area-inset-bottom, 0px));
  right: 19px;
  width: 42px;
  height: 42px;
  z-index: 13;
  display: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: opacity 0.3s ease, transform 0.2s ease;
}
#fnr-float-icon:active {
  transform: scale(0.9);
}
#fnr-float-icon svg {
  filter: drop-shadow(0 2px 8px rgba(0,0,0,0.6));
  animation: fnr-pulse 1.4s ease-in-out infinite;
}
#fnr-float-icon.playing circle {
  fill: #868afd;
  fill-opacity: 0.95;
}
#fnr-float-icon.playing path {
  fill: #fff;
}
@media (hover: none) and (pointer: coarse) {
  #fnr-sound-cursor,
  #fnr-sound-tooltip {
    display: none !important;
  }
}
#home > *:not(.parallax-layer) {
  position: relative;
  z-index: 3;
}
