/* ========================================================================
   18. PAINEIS, CARTOES E MOLDURAS
   ======================================================================== */
.fnr_feature_section {
  width: 100%;
  clear: both;
  float: left;
  position: relative;
  padding: 40px 0 50px 0;
  overflow: visible;
  box-sizing: border-box;
}
.fnr_feature_section .fnr_bg_blur img {
  display: none;
}
.fnr_feature_section .container {
  position: relative;
  z-index: 2;
}
.fnr_feature_panel {
  background-color: transparent;
  display: flex;
  align-items: center;
  gap: 56px;
  margin-bottom: 30px;
  padding: 30px 0px;
  margin-left: -25px;
  margin-right: -25px;
  padding-left: 25px;
  padding-right: 25px;
}
.fnr_feature_panel.fnr_reverse {
  flex-direction: row-reverse;
}
.fnr_panel_text {
  flex: 0 0 400px;
  max-width: 400px;
}
.fnr_panel_title {
  font-size: clamp(20px,2.5vw,28px);
  font-weight: 700;
  line-height: 1.2;
  background: linear-gradient(225deg,#f1b8dd 0%,#868afd 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 14px;
}
.fnr_panel_title.right {
  text-align: right;
}
.fnr_panel_desc {
  padding: 10px 0px 0px 0px;
  font-size: 14px;
  line-height: 1.8;
  color: rgba(255,255,255,0.6);
  margin-bottom: 24px;
}
.fnr_panel_desc.right {
  text-align: right;
}
.fnr_card_wrap {
  flex: 1;
  perspective: 900px;
}
.fnr_card {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  transform-style: preserve-3d;
  will-change: transform;
  transition: transform 0.06s linear;
  box-shadow: 0 0 0 1px rgba(255,255,255,0.07),0 28px 70px rgba(0,0,0,0.5);
  aspect-ratio: 16/9;
}
.fnr_card .fnr_frames img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.4s ease;
}
.fnr_card .fnr_frames img.fnr_active {
  opacity: 1;
}
.fnr_card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg,rgba(255,255,255,0.04) 0%,transparent 50%,rgba(0,0,0,0.18) 100%);
  pointer-events: none;
  z-index: 1;
}
.fnr_card_glow {
  position: absolute;
  inset: 0;
  border-radius: 20px;
  pointer-events: none;
  z-index: 2;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.1);
}
.fnr_frames video {
  display: none !important;
  opacity: 0;
  transition: opacity 0.5s ease;
}
.fnr_frames video.fnr_active {
  display: block !important;
  opacity: 1 !important;
}
.fnr_frames video,
.fnr_frames img {
  display: none !important;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.fnr_frames .fnr_active {
  display: block !important;
}
.fnr_frames::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: #000000;
  z-index: 10;
  pointer-events: none;
  opacity: 0;
}
