#fnr-lite-btn {
  position: fixed;
  right: 18px;
  bottom: 18px;
  bottom: calc(18px + env(safe-area-inset-bottom, 0px));
  width: 44px;
  height: 44px;
  margin: 0;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 50%;
  background: rgba(20,20,30,0.82);
  color: #fff;
  box-shadow: 0 4px 16px rgba(0,0,0,0.45);
  cursor: pointer;
  z-index: 13;
  opacity: 0.85;
  -webkit-tap-highlight-color: transparent;
  transition: background .25s ease, border-color .25s ease, opacity .25s ease, transform .2s ease;
}
#fnr-lite-btn svg {
  width: 20px;
  height: 20px;
  pointer-events: none;
  transition: fill .25s ease;
}
#fnr-lite-btn:active {
  transform: scale(0.92);
}
#fnr-lite-btn:focus-visible {
  outline: 2px solid #868afd;
  outline-offset: 3px;
  opacity: 1;
}
#fnr-lite-btn[aria-pressed="true"] {
  background: rgba(134,138,253,0.95);
  border-color: transparent;
  opacity: 1;
}
#fnr-lite-btn[aria-pressed="true"] svg {
  fill: currentColor;
}
#fnr-lite-label {
  position: fixed;
  right: 72px;
  bottom: 26px;
  bottom: calc(26px + env(safe-area-inset-bottom, 0px));
  z-index: 2147483646;
  pointer-events: none;
  white-space: nowrap;
  padding: 4px 12px;
  border-radius: 9999px;
  background: #1f1f1f;
  border: 1px solid #56585c;
  box-shadow: 0 6px 20px rgba(0,0,0,.45);
  color: #fff;
  font-family: 'JetBrains Mono', monospace;
  font-weight: 600;
  font-size: 11px;
  line-height: 18px;
  letter-spacing: 0.05em;
  opacity: 0;
  transform: translateX(6px);
  transition: opacity .2s ease,transform .2s ease,background-color .25s ease,color .25s ease,border-color .25s ease;
}
#fnr-lite-btn[aria-pressed="true"] + #fnr-lite-label {
  background: #6266eb;
  border-color: #6266eb;
}
#fnr-lite-label.show,
#fnr-lite-btn:focus-visible + #fnr-lite-label {
  opacity: 1;
  transform: none;
}
@media (hover: hover) {
  #fnr-lite-btn:hover {
    opacity: 1;
    border-color: rgba(134,138,253,0.6);
  }
  #fnr-lite-btn:hover + #fnr-lite-label {
    opacity: 1;
    transform: none;
  }
}
