/* ========================================================================
   22. GALERIA OPENSEA
   ======================================================================== */
.os-panel {
  --os-gut: 112px;
  --os-pt: 60px;
  --os-gap: clamp(10px,1.6vw,22px);
  --os-back: 40px;
  display: none;
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 12;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  color: #fff;
}
.os-panel.is-on {
  display: block;
}
.os-wrap {
  display: grid;
  grid-template-columns: var(--os-gut) minmax(0,1fr);
  align-items: start;
  box-sizing: border-box;
  min-height: 100%;
  padding: var(--os-pt) clamp(14px,2.5vw,36px) 72px 0;
}
.os-gutter {
  position: sticky;
  top: var(--os-pt);
  display: flex;
  justify-content: center;
  align-self: start;
}
.os-back {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--os-back);
  height: var(--os-back);
  padding: 0;
  border-radius: 50%;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  font: inherit;
}
.os-back svg {
  display: block;
  transition: transform .3s ease;
}
.os-back:hover svg,
.os-back:focus-visible svg {
  transform: translateX(-2px);
}
.os-back:focus-visible {
  outline: 2px solid rgba(134,138,253,.85);
  outline-offset: 3px;
}
.os-grid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: calc(var(--os-gap)*1.4) var(--os-gap);
  min-width: 0;
}
.os-item {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
a.os-card {
  display: block;
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
a.os-card:focus-visible {
  outline: 2px solid rgba(134,138,253,.85);
  outline-offset: 3px;
}
.os-card {
  position: relative;
  aspect-ratio: 1/1;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  contain: layout paint;
  background: #0b0b10;
  box-shadow: 0 0 0 1px rgba(255,255,255,.07),0 18px 44px rgba(0,0,0,.45);
}
.os-card::before {
  content: "";
  position: absolute;
  inset: -20px;
  z-index: -1;
  background: var(--p,linear-gradient(135deg,#2a2a4a,#12121c)) center/cover no-repeat;
  filter: blur(20px) brightness(.55);
}
.os-card video,
.os-card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  background: transparent;
}
.os-cap {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 2px 0;
}
.os-cap h2 {
  margin: 0;
  font-family: "JetBrains Mono",monospace;
  font-weight: 800;
  font-size: clamp(14px,1.7vw,22px);
  line-height: 1.2;
  color: #fff;
  overflow-wrap: anywhere;
}
.os-cap p {
  margin: 2px 0 0;
  font-size: 13px;
  color: rgba(255,255,255,.7);
}
.os-end {
  grid-column: 1/-1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  text-align: center;
  padding: 36px 20px;
  border-radius: 16px;
  background: rgba(255,255,255,.04);
  box-shadow: 0 0 0 1px rgba(255,255,255,.07);
}
.os-end h2 {
  margin: 0;
  font-family: "JetBrains Mono",monospace;
  font-weight: 800;
  font-size: clamp(18px,2.4vw,30px);
  color: #fff;
}
.os-end p {
  margin: 0;
  color: rgba(255,255,255,.7);
}
#portfolio.os-covered {
  visibility: hidden !important;
  transition: none !important;
}
#portfolio.os-covered *,
#portfolio.os-covered *::before,
#portfolio.os-covered *::after {
  visibility: hidden !important;
  transition: none !important;
}
html.os-moving #portfolio *,
html.os-moving .os-panel * {
