/* ========================================================================
   24. IMAGENS SOB DEMANDA (SPA)
   ======================================================================== */
img.spa-lazy:not(.spa-loaded) {
  background: linear-gradient(100deg,rgba(127,127,127,.10) 30%,rgba(127,127,127,.22) 50%,rgba(127,127,127,.10) 70%) 0 0/200% 100%;
  animation: spa_shimmer 1.4s linear infinite;
}
img.spa-defer {
  transition: filter .5s ease;
}
img.spa-defer.spa-blur:not(.spa-loaded) {
  filter: blur(18px);
  clip-path: inset(0);
}
img.spa-loaded {
  animation: none;
  background: none;
}
@media (prefers-reduced-motion:reduce) {
  img.spa-lazy:not(.spa-loaded) {
