   25. STORIES DO PERFIL
   ======================================================================== */
html.fnr-story-ready .profile-pic-wrapper:not(.fnr-story-play) .avatar {
  opacity: 0;
  transform: scale(0);
}
html.fnr-story-ready .profile-pic-wrapper:not(.fnr-story-play)::before {
  opacity: 0;
}
html.fnr-story-ready .profile-pic-wrapper:not(.fnr-story-play) .avatar {
  animation: fnr-safe-photo .5s ease 12s both;
}
html.fnr-story-ready .profile-pic-wrapper:not(.fnr-story-play)::before {
  animation: fnr-safe-ring .5s ease 12s both;
}
.profile-pic-wrapper.fnr-story-play .avatar {
  animation: fnr-photo-in .9s cubic-bezier(.22,1,.36,1) .05s both;
}
.profile-pic-wrapper.fnr-story-play::before {
  animation: fnr-ring-sweep 1.1s linear .45s both, stories-smooth-pulse 4s linear 1.55s infinite;
}
.profile-pic-wrapper::after {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 2px solid rgba(241,184,221,.65);
  opacity: 0;
  pointer-events: none;
  z-index: 1;
}
.profile-pic-wrapper.fnr-story-play::after {
  animation: fnr-ring-pulse 1.1s ease-out 1.5s 1 both;
}
@media (prefers-reduced-motion:reduce) {
  html.fnr-story-ready .profile-pic-wrapper .avatar {
    opacity: 1 !important;
    transform: none !important;
    animation: none !important;
  }
  html.fnr-story-ready .profile-pic-wrapper::before {
    opacity: 1 !important;
    animation: stories-smooth-pulse 4s linear infinite !important;
  }
  .profile-pic-wrapper::after {
    display: none;
  }
}
html.fnr-lite .profile-pic-wrapper .avatar {
  opacity: 1 !important;
  transform: none !important;
  animation: none !important;
}
html.fnr-lite .profile-pic-wrapper::before {
  opacity: 1 !important;
  clip-path: none !important;
}
html.fnr-lite .profile-pic-wrapper::after {
  display: none;
}
