/* ========================================================================
   27. CABECALHO DO CELULAR
   ======================================================================== */
.fnr-hdr-slot {
  --av: 40px;
  --rx: 5px;
  --rw: 2.5px;
  --gap: 14px;
  --it: clamp(34px,10.5vw,44px);
  position: relative;
  z-index: 3;
  flex: 0 0 auto;
  box-sizing: border-box;
  width: 0;
  height: calc(var(--av) + var(--rx) * 2);
  margin-right: 0;
  visibility: hidden;
  pointer-events: none;
  transition: width .45s cubic-bezier(.22,1,.36,1),margin-right .45s cubic-bezier(.22,1,.36,1),visibility 0s linear .45s;
}
html.spa-booting .fnr-hdr-slot,
body.fnr-inner-view .fnr-hdr-slot,
body.fnr-hdr-on .fnr-hdr-slot {
  width: calc(var(--av) + var(--rx) * 2);
  margin-right: var(--gap);
  visibility: visible;
  pointer-events: auto;
  transition-delay: 0s;
}
.fnr-hdr-pic {
  position: absolute;
  left: var(--rx);
  top: var(--rx);
  width: var(--av);
  height: var(--av);
  border-radius: 50%;
  cursor: pointer;
  z-index: 10;
  outline: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}
.fnr-hdr-pic:focus-visible {
  outline: 2px solid #868afd;
  outline-offset: calc(var(--rx) + 2px);
}
.fnr-hdr-avatar {
  position: relative;
  z-index: 2;
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  overflow: hidden;
  background: #212121;
}
.fnr-hdr-img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
  transition: transform .3s ease;
  pointer-events: none;
}
@media (hover:hover) {
  .fnr-hdr-pic:hover .fnr-hdr-img {
    transform: scale(1.06);
  }
}
.fnr-hdr-pic::before {
  content: '';
  position: absolute;
  inset: calc(var(--rx) * -1);
  border-radius: 50%;
  border: var(--rw) solid transparent;
  pointer-events: none;
  background: linear-gradient(#212121,#212121) padding-box, radial-gradient(circle at 15% 90%,#f9ed69 0%,#ff7a00 15%,transparent 60%) border-box, radial-gradient(circle at 85% 15%,#f1b8dd 0%,#e55ea3 35%,#b641b1 55%,#833ab4 75%,#868afd 100%) border-box;
  background-blend-mode: normal,screen;
  animation: stories-smooth-pulse 4s linear infinite;
  will-change: transform;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.fnr-hdr-pic::after {
  content: '';
  position: absolute;
  inset: calc(var(--rx) * -1);
  border-radius: 50%;
  border: 2px solid rgba(241,184,221,.65);
  opacity: 0;
  pointer-events: none;
  z-index: 1;
}
.fnr-hdr-pic.fnr-wait .fnr-hdr-avatar {
  opacity: 0;
  transform: scale(0);
  animation: none;
}
.fnr-hdr-pic.fnr-wait::before {
  opacity: 0;
  animation: none;
}
.fnr-hdr-pic.fnr-play .fnr-hdr-avatar {
  animation: fnr-photo-in .9s cubic-bezier(.22,1,.36,1) .05s both;
}
.fnr-hdr-pic.fnr-play::before {
  animation: fnr-ring-sweep 1.1s linear .45s both,stories-smooth-pulse 4s linear 1.55s infinite;
}
.fnr-hdr-pic.fnr-play::after {
  animation: fnr-ring-pulse 1.1s ease-out 1.5s 1 both;
}
.fnr-hdr-pic.fnr-leave {
  pointer-events: none;
}
.fnr-hdr-pic.fnr-leave .fnr-hdr-avatar {
  animation: fnr-photo-out .38s cubic-bezier(.22,1,.36,1) both;
}
.fnr-hdr-pic.fnr-leave::before {
  animation: fnr-ring-out .34s ease-in both;
}
.fnr-hdr-pic.fnr-leave::after {
  animation: none;
  opacity: 0;
}
.fnr-hdr-pic.is-open::before {
  animation: none;
  opacity: 1;
  background: linear-gradient(#212121,#212121) padding-box, radial-gradient(circle at 15% 90%,#f9ed69 0%,#ff7a00 15%,transparent 60%) border-box, radial-gradient(circle at 85% 15%,#fff 0%,#fff 35%,#f1b8dd 55%,#f1b8dd 100%) border-box;
  background-blend-mode: normal,screen;
}
.fnr-hdr-social {
  visibility: hidden;
  transition: visibility 0s linear .7s;
}
.fnr-hdr-slot.is-open .fnr-hdr-social {
  visibility: visible;
  transition-delay: 0s;
}
.fnr-hdr-item a {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  border-radius: 50%;
  background: #1f1f1f;
  border: 1px solid rgba(255,255,255,.25);
  box-shadow: inset 0 0 0 3px rgba(255,255,255,.3);
  text-decoration: none;
  transition: background .3s ease,box-shadow .3s ease;
  -webkit-tap-highlight-color: transparent;
}
.fnr-hdr-item a:hover,
.fnr-hdr-item a:focus-visible {
  background: #515151;
  box-shadow: inset 0 0 0 5px rgba(255,255,255,.7),0 0 20px rgba(255,255,255,.2);
  outline: none;
}
