/* ========================================================================
   29. REGUA DE ROLAGEM, MENU FLUTUANTE E LINHA DO TEMPO
   ======================================================================== */
#op-ruler {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 0;
  z-index: 13;
  pointer-events: none;
  display: none;
  --opr-fg: #1f1f1f;
  --opr-dim: rgba(0,0,0,.28);
  --opr-bd: #eee;
  --opr-bg: #fff;
  --opr-tx: #000;
}
body.dark #op-ruler {
  --opr-fg: #fff;
  --opr-dim: rgba(255,255,255,.3);
  --opr-bd: #56585c;
  --opr-bg: #1f1f1f;
  --opr-tx: #fff;
}
html.op-on #op-ruler {
  display: block;
}
body:has(.os-panel.is-on) #op-ruler {
  display: none;
}
#op-ruler .opr-track {
  position: absolute;
  right: 18px;
  top: 14vh;
  bottom: 14vh;
  width: 26px;
  background-image: repeating-linear-gradient(to bottom,var(--opr-dim) 0,var(--opr-dim) 1px,transparent 1px,transparent 2%), repeating-linear-gradient(to bottom,var(--opr-fg) 0,var(--opr-fg) 1px,transparent 1px,transparent 10%);
  background-size: 7px 100%,14px 100%;
  background-position: right top,right top;
  background-repeat: no-repeat;
}
#op-ruler .opr-track::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -1px;
  width: 14px;
  height: 1px;
  background: var(--opr-fg);
}
#op-ruler .opr-mark {
  position: absolute;
  right: 0;
  width: 20px;
  height: 2px;
  margin-top: -1px;
  background: var(--opr-fg);
  opacity: .55;
}
#op-ruler .opr-mark.on {
  width: 26px;
  opacity: 1;
}
#op-ruler .opr-cur {
  position: absolute;
  right: 0;
  top: 0;
  display: flex;
  align-items: center;
  transform: translate3d(0,-50%,0);
  will-change: top;
}
#op-ruler .opr-chip {
  padding: 5px 9px;
  text-align: right;
  white-space: nowrap;
  color: var(--opr-tx);
  border: 2px solid var(--opr-bd);
  background-color: var(--opr-bg);
  font-family: "JetBrains Mono",monospace;
  font-size: 11px;
  line-height: 1.35;
  font-weight: 500;
}
body.dark #op-ruler .opr-chip {
  background-image: var(--fnr-dots);
}
#op-ruler .opr-pct {
  display: block;
  font-size: 13px;
  font-weight: 800;
}
#op-ruler .opr-ttl {
  display: block;
  opacity: .85;
}
#op-ruler .opr-needle {
  display: block;
  width: 26px;
  height: 2px;
  background: var(--opr-fg);
}
#op-ruler .opr-chip,
body.dark #op-ruler .opr-chip {
  color: #fff;
  border-radius: 15px;
  background: rgba(255,255,255,.1);
  background-image: none;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  border: 1px solid #56585c;
  box-shadow: 0 8px 32px 0 rgba(0,0,0,.3);
}
body:not(.dark) #op-ruler .opr-chip {
  background: rgba(20,20,30,.45);
}
html.fnr-lite #op-ruler .opr-chip {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}
#op-ruler .opr-track {
  background: none;
}
#op-ruler .opr-track::after,
#op-ruler .opr-marks {
  display: none;
}
@media (max-width:1200px) {
  html.op-on #op-ruler {
    display: block;
  }
  #op-ruler .opr-track {
    position: static;
    width: auto;
    height: auto;
    background: none;
  }
  #op-ruler .opr-track::after,
  #op-ruler .opr-marks,
  #op-ruler .opr-needle {
    display: none;
  }
  #op-ruler .opr-cur {
    position: fixed;
    left: 50%;
    right: auto;
    top: auto !important;
    bottom: calc(18px + env(safe-area-inset-bottom,0px));
    transform: translateX(-50%);
    will-change: auto;
    max-width: calc(100vw - 140px);
  }
  #op-ruler .opr-chip {
    display: flex;
    align-items: baseline;
    gap: 10px;
    text-align: left;
    box-sizing: border-box;
    height: 44px;
    align-items: center;
    padding: 0 14px;
    border-radius: 15px;
    color: #fff;
    background: rgba(255,255,255,.1);
    background-image: none;
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
    border: 1px solid #56585c;
    box-shadow: 0 8px 32px 0 rgba(0,0,0,.3);
  }
  body:not(.dark) #op-ruler .opr-chip {
    background: rgba(20,20,30,.45);
  }
  body.dark #op-ruler .opr-chip {
    background-image: none;
  }
  #op-ruler .opr-pct {
    display: inline;
    flex: 0 0 auto;
  }
  #op-ruler .opr-ttl {
    display: inline;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  html.fnr-lite #op-ruler .opr-chip {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
/* botao flutuante "Menu" tambem nas paginas do blog (celular) */
@media (max-width:1200px) {
  body.fnr-blog-view #op-ruler {
    display: block;
  }
}
.ff-grip {
  display: none;
}
@media (max-width:1200px) {
  html.fnr-flow .flpnr_tm_topbar .trigger {
    display: none;
  }
  html.fnr-flow #op-ruler .opr-cur {
    pointer-events: auto;
    touch-action: none;
    cursor: grab;
    -webkit-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
    -webkit-tap-highlight-color: transparent;
  }
  html.fnr-flow .ff-grip {
    display: inline-flex;
    align-self: center;
    color: #fff;
    opacity: .75;
  }
  html.fnr-flow .ff-grip svg {
    display: block;
  }
  html.fnr-flow #op-ruler .opr-chip {
    transition: transform .24s cubic-bezier(.2,.9,.25,1.2),border-color .2s ease,box-shadow .25s ease,background-color .25s ease,color .25s ease;
  }
  html.fnr-flow #op-ruler .opr-pct {
    font-variant-numeric: tabular-nums;
    min-width: 3ch;
    text-align: right;
  }
  html.fnr-flow #op-ruler .opr-cur.ff-press .opr-chip {
    transform: scale(.96);
  }
  html.fnr-flow #op-ruler .opr-cur.ff-live .opr-chip {
    transform: scale(1.05);
    border-color: rgba(134,138,253,.85);
    box-shadow: 0 0 0 1px rgba(134,138,253,.35),0 10px 34px rgba(134,138,253,.4);
  }
  html.fnr-flow-open #op-ruler {
    z-index: 30;
  }
}
@media (max-width:1200px) {
  html body #op-ruler .opr-chip {
    transition: background-color .25s ease,color .25s ease,border-color .25s ease;
  }
}
#fnr-flow {
  position: fixed;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 25;
  visibility: hidden;
  pointer-events: none;
  transition: visibility 0s linear .28s;
}
#fnr-flow.on {
  visibility: visible;
  transition-delay: 0s;
}
#fnr-flow .ff-dim {
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  background: rgba(5,5,14,.55);
  opacity: 0;
  transition: opacity .26s ease;
}
#fnr-flow.on .ff-dim {
  opacity: 1;
}
#fnr-flow .ff-panel {
  position: absolute;
  left: 0;
  right: 0;
  margin: 0 auto;
  width: min(calc(100vw - 48px),320px);
  box-sizing: border-box;
  padding: 8px 0;
  border-radius: 18px;
  background: rgba(20,20,30,.8);
  border: 1px solid rgba(255,255,255,.18);
  box-shadow: 0 8px 32px 0 rgba(0,0,0,.35);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  transform-origin: 50% 100%;
  opacity: 0;
  transform: translate3d(0,18px,0) scale(.88);
  transition: transform .38s cubic-bezier(.2,.9,.25,1.1),opacity .2s ease;
}
#fnr-flow.on .ff-panel {
  opacity: 1;
  transform: translate3d(0,0,0) scale(1);
}
html.fnr-lite #fnr-flow .ff-panel {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  background: rgba(20,20,30,.92);
}
#fnr-flow .ff-list {
  position: relative;
  --ff-lx: 77px;
}
#fnr-flow .ff-rail {
  position: absolute;
  top: calc(var(--ff-rh,44px) / 2);
  bottom: calc(var(--ff-rh,44px) / 2);
  left: var(--ff-lx);
  width: 2px;
  margin-left: -1px;
  border-radius: 2px;
  background: rgba(255,255,255,.14);
  overflow: hidden;
}
#fnr-flow .ff-fill {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  transform-origin: 50% 0;
  transform: scaleY(0);
  background: linear-gradient(180deg,#f1b8dd 0%,#868afd 100%);
  transition: transform .09s linear;
  will-change: transform;
}
#fnr-flow .ff-lens {
  position: absolute;
  left: 6px;
  right: 6px;
  top: 0;
  height: var(--ff-rh,44px);
  opacity: 0;
  transition: transform .17s cubic-bezier(.25,.9,.3,1),opacity .15s ease;
  will-change: transform;
}
#fnr-flow .ff-lens:before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 3px;
  bottom: 3px;
  border-radius: 12px;
  background: rgba(255,255,255,.13);
  border: 1px solid rgba(255,255,255,.3);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.18);
}
#fnr-flow .ff-item {
  position: relative;
  z-index: 1;
  height: var(--ff-rh,44px);
  display: grid;
  grid-template-columns: 44px 18px 1fr;
  column-gap: 10px;
  align-items: center;
  padding: 0 16px 0 14px;
  opacity: .55;
  transition: opacity .18s ease;
}
#fnr-flow.on .ff-item {
  animation: ffRowIn .4s cubic-bezier(.2,.9,.25,1) backwards;
  animation-delay: calc(var(--ri,0) * 26ms);
}
#fnr-flow .ff-item.sel {
  opacity: 1;
}
#fnr-flow .ff-pct {
  text-align: right;
  font-family: "JetBrains Mono",monospace;
  font-size: 11px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: .02em;
  font-variant-numeric: tabular-nums;
  color: rgba(255,255,255,.65);
  transition: color .18s ease;
}
#fnr-flow .ff-item.sel .ff-pct {
  color: #fff;
  font-weight: 700;
}
#fnr-flow .ff-node {
  display: block;
}
#fnr-flow .ff-dot {
  display: block;
  width: 10px;
  height: 10px;
  margin: 0 auto;
  border-radius: 50%;
  box-sizing: border-box;
  background: #1c1d29;
  border: 1.5px solid rgba(255,255,255,.38);
  transition: transform .22s cubic-bezier(.2,.9,.25,1.5),background .2s ease,border-color .2s ease,box-shadow .2s ease;
}
#fnr-flow .ff-item.past .ff-dot {
  background: linear-gradient(225deg,#f1b8dd 0%,#868afd 100%) border-box;
  border-color: transparent;
}
#fnr-flow .ff-item.sel .ff-dot {
  transform: scale(1.3);
  box-shadow: 0 0 0 3px rgba(134,138,253,.28);
}
#fnr-flow .ff-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: "JetBrains Mono",monospace;
  font-size: 14px;
  line-height: 1.25;
  font-weight: 600;
  color: #fff;
  transition: transform .22s cubic-bezier(.2,.9,.25,1.2);
}
#fnr-flow .ff-item.sel .ff-name {
  transform: translate3d(4px,0,0);
}
.opr-cur.ff-hint .ff-grip {
  animation: ffGrip .9s ease-in-out 3;
}
.opr-cur.ff-hint .opr-chip {
  animation: ffPulse 1.1s ease-in-out 3;
}
.ff-tip {
