@media (max-width:1200px) {
  html.fnr-flow .ff-tip {
    display: flex;
    align-items: center;
    gap: 5px;
    position: absolute;
    left: 50%;
    bottom: 100%;
    margin-bottom: 12px;
    transform: translateX(-50%);
