/* ========================================================================
   31. INTERESSES E CARTOES DO SOBRE
   ======================================================================== */
.flpnr_tm_interests .in-interests .widget a {
  display: block;
  position: relative;
  height: 145px;
  line-height: 0;
  text-decoration: none;
  overflow: hidden;
  isolation: isolate;
  background: #1f1f1f;
}
.fnr-tri-video {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
  background: #1f1f1f;
  filter: grayscale(1) contrast(1.15) brightness(.56);
  transition: filter .45s ease;
}
.flpnr_tm_interests .in-interests .widget a::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  background: #1f1f1f;
  mix-blend-mode: lighten;
  opacity: 1;
  transition: opacity .45s ease;
  pointer-events: none;
}
@media (hover:hover) {
  .flpnr_tm_interests .in-interests .widget a:hover .fnr-tri-video {
    filter: none;
  }
  .flpnr_tm_interests .in-interests .widget a:hover::after {
    opacity: 0;
  }
}
.flpnr_tm_interests .in-interests .widget a:focus-visible .fnr-tri-video,
.flpnr_tm_interests .in-interests .widget a.is-colored .fnr-tri-video {
  filter: none;
}
.flpnr_tm_interests .in-interests .widget a:focus-visible::after,
.flpnr_tm_interests .in-interests .widget a.is-colored::after {
  opacity: 0;
}
.flpnr_tm_interests .in-interests .widget a.is-static {
  cursor: pointer;
}
@media (prefers-reduced-motion:reduce) {
  .fnr-tri-video,
  .flpnr_tm_interests .in-interests .widget a::after {
    transition: none;
  }
}
