/* ========================================================================
   33. BOTOES FLUTUANTES E PERFORMANCE NO TOUCH
   ======================================================================== */
/* FABs no celular: Menu / Modo leve / Musica com a mesma estetica */
html body #fnr-lite-btn {
  z-index: 2147483646;
}
html body #preloader,
html body #spa-loader {
  z-index: 2147483647;
}
/* "Menu Fillter" (LinkList0010) é um filtro antigo que não é usado em nenhum lugar: não deve aparecer no cabeçalho */
html body #LinkList0010,
html body .flpnr_tm_topbar .log-mobile .LinkList {
  display: none !important;
}
@media (max-width:1200px) {
  html body #fnr-lite-btn,
  html body #fnr-float-icon {
    width: 44px;
    height: 44px;
    box-sizing: border-box;
    border-radius: 15px;
    color: #fff !important;
    text-shadow: none;
    background-color: rgba(20,20,30,.45) !important;
    background-image: none !important;
    border: 1px solid #56585c !important;
    box-shadow: 0 8px 32px 0 rgba(0,0,0,.3) !important;
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
    opacity: 1;
    transform: translateZ(0);
    will-change: transform;
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
    transition: opacity .3s ease,transform .2s ease,background-color .25s ease,color .25s ease,border-color .25s ease;
  }
  html body #fnr-lite-btn {
    right: 18px;
    bottom: calc(18px + env(safe-area-inset-bottom,0px));
  }
  html body #fnr-float-icon {
    right: 18px;
    bottom: calc(74px + env(safe-area-inset-bottom,0px));
  }
  html body #fnr-lite-btn::before,
  html body #fnr-lite-btn::after,
  html body #fnr-float-icon::before,
  html body #fnr-float-icon::after {
    display: none;
  }
  html body.dark #fnr-lite-btn,
  html body.dark #fnr-float-icon {
    background-color: rgba(255,255,255,.1) !important;
  }
  /* estado ativo (modo leve ligado / música tocando) */
  html body #fnr-lite-btn[aria-pressed="true"],
  html body #fnr-float-icon.playing {
    color: #fff !important;
    background-color: rgba(98,102,235,.92) !important;
    border-color: rgba(255,255,255,.35) !important;
    box-shadow: 0 8px 28px rgba(98,102,235,.35) !important;
  }
  /* icone da musica usa a cor do texto do botao */
  html body #fnr-float-icon svg {
    filter: none;
  }
  html body #fnr-float-icon path:first-of-type {
    fill: currentColor;
  }
  html body #fnr-float-icon path:not(:first-of-type) {
    stroke: currentColor;
  }
  html body #fnr-float-icon.playing path {
    fill: currentColor;
  }
  /* fluidez no scroll (iOS): camada de composição própria também no Menu */
  html body #op-ruler .opr-cur {
    transform: translate3d(-50%,0,0);
    -webkit-transform: translate3d(-50%,0,0);
  }
  html body #op-ruler .opr-chip {
    will-change: transform;
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
  }
}
/* ===== Desktop: botão de energia (Modo leve) com a mesma estética dos FABs do celular ===== */
