/* ===== Botão de áudio (cursor do desktop, dica e ícone flutuante do celular): fade in / fade out =====
   Mesma linguagem do .fnr-tap-hint: opacidade + blur + leve deslocamento, easing cubic-bezier(.22,1,.36,1) */
html body #fnr-sound-cursor,
html body #fnr-sound-tooltip,
html body #fnr-float-icon {
  display: block;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  filter: blur(4px);
  translate: 0 -8px;
  transition: opacity .85s cubic-bezier(.22,1,.36,1), filter .85s cubic-bezier(.22,1,.36,1), translate .85s cubic-bezier(.22,1,.36,1), visibility 0s linear .85s, transform .2s ease,background-color .45s ease,color .25s ease,border-color .45s ease,box-shadow .45s ease;
}
html body #fnr-sound-cursor.fnr-show,
html body #fnr-sound-tooltip.fnr-show,
html body #fnr-float-icon.fnr-show {
  opacity: 1;
  visibility: visible;
  filter: blur(0);
  translate: 0 0;
  transition: opacity .6s cubic-bezier(.22,1,.36,1), filter .6s cubic-bezier(.22,1,.36,1), translate .6s cubic-bezier(.22,1,.36,1), visibility 0s linear 0s, transform .2s ease,background-color .45s ease,color .25s ease,border-color .45s ease,box-shadow .45s ease;
}
html body #fnr-float-icon.fnr-show {
  pointer-events: auto;
}
@media (hover:none) and (pointer:coarse) {
  html body #fnr-sound-cursor,
  html body #fnr-sound-tooltip {
    display: none !important;
  }
}
@media (prefers-reduced-motion:reduce) {
  html body #fnr-sound-cursor,
  html body #fnr-sound-tooltip,
  html body #fnr-float-icon,
  html body #fnr-sound-cursor.fnr-show,
  html body #fnr-sound-tooltip.fnr-show,
  html body #fnr-float-icon.fnr-show {
    filter: none;
    translate: none;
    transition: opacity .4s ease,visibility 0s linear .4s;
  }
  html body #fnr-sound-cursor.fnr-show,
  html body #fnr-sound-tooltip.fnr-show,
  html body #fnr-float-icon.fnr-show {
    transition: opacity .4s ease,visibility 0s;
  }
}
/* ===== FNR · PERFORMANCE iOS / TOUCH ===== */
@media (hover:none) and (pointer:coarse) {
  /* blur de fundo recompoe tudo que esta atras a cada frame de scroll; bg fixo repinta no iOS */
  html body *,
  html body *::before,
  html body *::after {
    -webkit-backdrop-filter: none !important;
    backdrop-filter: none !important;
    background-attachment: scroll !important;
  }
  /* cartoes de vidro: sombra enorme + gradiente holografico de 350% animado (hover "grudado" no touch) */
  html body .glass-card,
  html body .glass-card:hover {
    box-shadow: none !important;
    transform: none !important;
  }
  html body .glass-card::before {
    display: none !important;
  }
  /* camadas de GPU permanentes consomem memoria do Safari */
  html body .parallax-layer,
  html body .fnr_card,
  html body .flpnr_tm_testimonials .owl-carousel .owl-stage,
  html body .profile-pic-wrapper::before,
  html body .fnr-hdr-pic::before,
  html body #fnr-flow .ff-fill {
    will-change: auto !important;
  }
  /* canvas de pontos fullscreen (so desktop) */
  html body #fnr-dots {
    display: none !important;
  }
  /* galerias de Projetos e Identidades: sem transicoes/hover, e isolamento de layout/pintura por miniatura */
  html body .post-gallery a img,
  html body .split-img img,
  html body .nn-thumb,
  html body .nn-thumb img,
  html body .fnr-pj-cap {
    transition: none !important;
  }
  html body .post-gallery a:hover img,
  html body .nn-thumb:hover {
    transform: none !important;
  }
  html body .post-gallery a,
  html body a.fnr-pj-open,
  html body .nn-thumb {
    contain: layout paint;
  }
}
/* ========================================================================
   34. PLACEHOLDERS, BOTOES PILULA E EFEITO DIFFERENCE
   ======================================================================== */
/* ===================== FNR · AJUSTES (performance, placeholders, botoes) ===================== */
/* --- Placeholders: a area da midia fica marcada ate carregar.
       Cor estatica (o shimmer animava background-position em centenas de imagens = repintura a cada frame) --- */
html body img.spa-lazy:not(.spa-loaded) {
  background: rgba(127,127,127,.14) !important;
  animation: none !important;
}
html body img.spa-loaded {
  background: none;
  animation: fnr-img-in .35s ease both;
}
html body .spa-page .video-grid-item {
  background-color: rgba(127,127,127,.14);
}
/* secao ainda nao montada: reserva espaco e marca a area (sem salto de layout) */
html body .spa-page .spa-mount:empty {
  min-height: 70vh;
  background: rgba(127,127,127,.06);
}
/* touch/iOS: sem blur(18px) por imagem durante o carregamento (caro no Safari); fica o placeholder */
@media (hover:none),(pointer:coarse) {
  html body img.spa-defer.spa-blur:not(.spa-loaded) {
    filter: none;
    clip-path: none;
    opacity: 0;
  }
  html body img.spa-defer {
    transition: none;
  }
}
@media (prefers-reduced-motion:reduce) {
  html body img.spa-loaded {
    animation: none;
  }
}
/* --- Botoes: bordas totalmente circulares (pilula) --- */
html:root body .nn5-btn,
html:root body .nn5-btn.nn5-sm,
html:root body .nn5-vbtn,
html:root body .vid-btn,
html:root body .char-btn,
html:root body .gt-nav-btn,
html:root body .vol-btn,
html:root body .fnr-vlb-btn,
html:root body #fnr-vlb .fnr-vlb-btn,
html:root body #vid-lb-close,
html:root body #vid-lb-audio,
html:root body .fnr-yt-play,
html:root body .fnr-pj-x,
html:root body .nn-close,
html:root body .mfp-close,
html:root body #fnr-lite-btn,
html:root body #fnr-float-icon,
html:root body #op-ruler .opr-chip {
  border-radius: 9999px !important;
}
html:root body .flpnr_tm_pricing .flpnr_tm_button a {
  min-height: 40px;
}
/* --- Botoes flutuantes (Menu do celular, Modo leve, Musica) e botoes de fechar:
       texto e icone brancos com mix-blend-mode: difference = sempre invertidos em relacao ao fundo.
       Sem fundo, sombra ou blur (o blur por tras recompunha a tela a cada frame de scroll) --- */
html:root body #fnr-lite-btn,
html:root body #fnr-float-icon {
  color: #fff !important;
  background: transparent !important;
  background-image: none !important;
  border: 1.5px solid #fff !important;
  box-shadow: none !important;
  text-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  mix-blend-mode: difference;
  will-change: auto;
}
html:root body #fnr-lite-btn,
html:root body #fnr-float-icon {
  width: 44px;
  height: 44px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
html:root body #fnr-float-icon svg {
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
}
html:root body #fnr-float-icon svg circle {
  fill: transparent !important;
}
html:root body #fnr-float-icon path:first-of-type {
  fill: currentColor;
}
html:root body #fnr-float-icon path:not(:first-of-type) {
  stroke: currentColor;
}
html:root body #fnr-lite-btn:focus-visible {
  outline-color: #fff;
}
/* ativo (modo leve ligado / musica tocando): pilula branca com o icone "vazado" */
html:root body #fnr-lite-btn[aria-pressed="true"],
html:root body #fnr-float-icon.playing {
  background: #fff !important;
  color: #000 !important;
}
html:root body #fnr-float-icon.playing path {
  fill: currentColor;
}
/* Menu do celular: a regua inteira entra em difference (a pilula fica dentro de um contexto proprio) */
@media (max-width:1200px) {
  html:root body #op-ruler {
    mix-blend-mode: difference;
  }
  html:root body #op-ruler .opr-chip,
  html:root body #op-ruler .opr-cur.ff-live .opr-chip {
    color: #fff !important;
    background: transparent !important;
    background-image: none !important;
    border: 1.5px solid #fff !important;
    box-shadow: none !important;
    -webkit-backdrop-filter: none !important;
    backdrop-filter: none !important;
    will-change: auto !important;
  }
  html:root body #op-ruler .ff-grip,
  html:root body #op-ruler .ff-tip {
    color: #fff !important;
    text-shadow: none !important;
  }
  html:root body #op-ruler .ff-tip svg {
    fill: #fff !important;
    filter: none !important;
  }
}
/* fechar de pop-ups (projetos, Identidades, videos) */
html:root body .fnr-pj-x,
html:root body .nn-close,
html:root body #vid-lb-close,
html:root body .fnr-vlb-close,
html:root body #fnr-vlb .fnr-vlb-close {
  color: #fff !important;
  background: transparent !important;
  border: 1.5px solid #fff !important;
  box-shadow: none !important;
  mix-blend-mode: difference;
}
/* ========================================================================
   34B. SEGUNDA NAVEGACAO: PERFORMANCE NO CELULAR
   ======================================================================== */
/* paginas da 2a navegacao sao muito altas: animar o transform da pagina inteira
   ao chegar nela cria uma camada gigante na GPU (travamento e areas em branco no iPhone) */
@media (max-width:1200px) {
  html.op-on.op-s2 .flpnr_tm_section.op-jump {
    animation: none;
  }
}
/* 3D da Producao Cultural: o dedo na vertical rola a pagina em vez de travar no canvas */
/* touch: imagens aparecem direto, sem fade (o fade deixava a area vazia por mais tempo) */
@media (hover:none),(pointer:coarse) {
  html body img.spa-loaded {
    animation: none;
  }
}
/* ========================================================================
   34C. BOTOES: ESTETICA UNICA (VIDRO DOS BOTOES "VER PROJETOS")
   referencia: .fnr_panel_btn da pagina inicial
   texto  = pilula de 44px, 13px, peso 600
   compacto = mesmo vidro, tamanho original (controles do 3D e do player)
   icone  = mesmo vidro, circulo no tamanho original
   (botoes flutuantes e de fechar mantem o efeito difference da secao 34)
   ======================================================================== */
html:root body .flpnr_tm_button a,
html:root body .fnr_panel_btn,
html:root body .fnr-pj-btn,
html:root body .nn-btn-dl,
html:root body .nn-modal .nn-btn-dl,
html:root body input[type="submit"],
html:root body .vid-btn,
html:root body .char-btn,
html:root body .nn5-vbtn,
html:root body .nn5-btn,
html:root body .nn5-tplay,
html:root body .nn5-rz-btn,
html:root body .vol-btn,
html:root body .stories-arrow,
html:root body .gt-nav-btn,
html:root body #vid-lb-audio,
html:root body .fnr-vlb-btn:not(.fnr-vlb-close),
html:root body .fnr-yt-play {
  isolation: isolate;
  overflow: hidden;
  color: #fff !important;
  text-decoration: none !important;
  text-shadow: 0 1px 2px rgba(0,0,0,.35);
  background-color: rgba(20,20,28,.45) !important;
  background-image: linear-gradient(135deg,rgba(255,255,255,.20) 0%,rgba(255,255,255,.07) 55%,rgba(255,255,255,.12) 100%) !important;
  -webkit-backdrop-filter: blur(8px) saturate(140%);
  backdrop-filter: blur(8px) saturate(140%);
  border: 1px solid rgba(255,255,255,.12) !important;
  box-shadow: 0 8px 32px rgba(0,0,0,.30),inset 0 1px 0 rgba(255,255,255,.28),inset 0 -1px 0 rgba(255,255,255,.06) !important;
  border-radius: 9999px !important;
  transition: transform .45s cubic-bezier(.22,1,.36,1),box-shadow .45s ease,background-color .45s ease,border-color .45s ease,color .3s ease;
  -webkit-tap-highlight-color: transparent;
}
/* botoes que nao tinham posicao propria: o anel e o brilho precisam de referencia */
html:root body .flpnr_tm_button a,
html:root body .fnr_panel_btn,
html:root body input[type="submit"],
html:root body .fnr-pj-btn,
html:root body .nn-btn-dl,
html:root body .vid-btn,
html:root body .char-btn,
html:root body .nn5-vbtn,
html:root body .nn5-btn,
html:root body .nn5-tplay,
html:root body .nn5-rz-btn,
html:root body .vol-btn {
  position: relative;
}
/* anel de borda em degrade (igual ao da referencia) */
html:root body .flpnr_tm_button a::after,
html:root body .fnr_panel_btn::after,
html:root body .fnr-pj-btn::after,
html:root body .nn-btn-dl::after,
html:root body .vid-btn::after,
html:root body .char-btn::after,
html:root body .nn5-vbtn::after,
html:root body .nn5-btn::after,
html:root body .nn5-tplay::after,
html:root body .nn5-rz-btn::after,
html:root body .vol-btn::after,
html:root body .stories-arrow::after,
html:root body .gt-nav-btn::after,
html:root body #vid-lb-audio::after,
html:root body .fnr-vlb-btn:not(.fnr-vlb-close)::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg,rgba(255,255,255,.65) 0%,rgba(255,255,255,.10) 38%,rgba(255,255,255,.10) 62%,rgba(255,255,255,.40) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude,linear-gradient(#000 0 0);
  pointer-events: none;
  z-index: -1;
}
/* brilho que passa no hover (igual ao da referencia) */
html:root body .flpnr_tm_button a::before,
html:root body .fnr_panel_btn::before,
html:root body .fnr-pj-btn::before,
html:root body .nn-btn-dl::before,
html:root body .vid-btn::before,
html:root body .char-btn::before,
html:root body .nn5-vbtn::before,
html:root body .nn5-btn::before,
html:root body .nn5-tplay::before,
