html:root body .gt-nav-btn::before,
html:root body #vid-lb-audio::before,
html:root body .fnr-vlb-btn:not(.fnr-vlb-close)::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -60%;
  width: 50%;
  background: linear-gradient(105deg,rgba(255,255,255,0) 0%,rgba(100,200,255,.16) 30%,rgba(255,255,255,.34) 50%,rgba(255,100,255,.16) 70%,rgba(255,255,255,0) 100%);
  transform: translateX(0) skewX(-18deg);
  opacity: 0;
  pointer-events: none;
  z-index: -1;
}
