/* ========================================================================
   34E. MENU FLUTUANTE DO CELULAR (segurar e arrastar a pilula)
   painel solido com pontos do tema, trilha em degrade, selecao em pilula;
   "Voltar para o Inicio" separado da trilha, com destaque proprio
   ======================================================================== */
html body #fnr-flow .ff-dim {
  background: rgba(10,10,14,.6);
}
html body #fnr-flow .ff-panel {
  background: linear-gradient(135deg,rgba(72,72,72,.90) 0%,rgba(134,138,253,.15) 50%,rgba(38,38,38,.85) 100%);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 22px;
  box-shadow: 0 8px 32px rgba(0,0,0,.35),0 2px 8px rgba(0,0,0,.15),inset 0 1px 0 rgba(255,255,255,.07);
  -webkit-backdrop-filter: blur(48px);
  backdrop-filter: blur(48px);
}
/* trilha cinza do tema, preenchimento no degrade rosa/lilas */
html body #fnr-flow .ff-rail {
  background: #3a3c41;
}
/* item em foco: pilula de vidro igual aos botoes */
html body #fnr-flow .ff-lens:before {
  border-radius: 9999px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.22);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.16);
}
/* texto no padrao do menu do computador: cinza, branco no item em foco.
   As cores do tema ficam so na linha do tempo (trilha e pontos) */
html body #fnr-flow .ff-name {
  color: #bbb;
}
html body #fnr-flow .ff-item.sel .ff-name {
  color: #fff;
}
/* pagina onde voce esta: anel rosa no ponto */
/* linha do tempo com as mesmas cores do menu do desktop */
html body #fnr-flow .ff-rail {
  background: #56585c;
}
html body #fnr-flow .ff-fill {
  background: #fff;
}
html body #fnr-flow .ff-dot {
  background: #6d6f75;
  border: 0;
  box-shadow: none;
}
html body #fnr-flow .ff-item.past .ff-dot {
  background: #fff;
  border: 0;
}
html body #fnr-flow .ff-item.sel .ff-dot {
  background: #fff;
  transform: scale(1.45);
  box-shadow: 0 0 0 3px rgba(255,255,255,.16);
}
html body #fnr-flow .ff-item.cur .ff-dot {
  background: #fff;
  border: 0;
  box-shadow: 0 0 0 3px rgba(255,255,255,.16);
}
html body #fnr-flow .ff-pct {
  color: #8d8f95;
}
html body #fnr-flow .ff-item.sel .ff-pct {
  color: #fff;
}
/* --- Voltar para o Inicio: faixa levemente rebaixada, fora da trilha --- */
html body #fnr-flow .ff-list.ff-has-back .ff-rail {
  clip-path: inset(var(--ff-rh,44px) 0 0 0);
}
html body #fnr-flow .ff-item.ff-back {
  --bk-in: 12px;  /* margem lateral = 8px de padding do menu + 4px do topo do botão */
  --bk-r: 10px;   /* curva do menu (22px) menos a margem (12px): borda paralela à do menu */
}
/* repouso: botão afundado */
html body #fnr-flow .ff-item.ff-back::before {
  content: "";
  position: absolute;
  left: var(--bk-in);
  right: var(--bk-in);
  top: 4px;
  bottom: 4px;
  z-index: -1;
  box-sizing: border-box;
  border: 1px solid transparent;
  border-radius: var(--bk-r);
  background: rgba(0,0,0,.18);
  box-shadow: inset 0 1px 2px rgba(0,0,0,.35),0 1px 0 rgba(255,255,255,.05);
  transition: background .35s ease,box-shadow .35s ease,border-color .35s ease;
}
html body #fnr-flow .ff-item.ff-back.sel::before {
  background: transparent;
  box-shadow: none;
  border-color: rgba(255,255,255,.22);
}
html body #fnr-flow .ff-item.ff-back .ff-node {
  display: none;
}
html body #fnr-flow .ff-item.ff-back .ff-pct {
  justify-self: end;
  color: #bbb;
  font-size: 14px;
  font-weight: 700;
}
html body #fnr-flow .ff-item.ff-back .ff-name {
  grid-column: 2 / 4;
  color: #bbb;
  font-size: 12px;
  letter-spacing: .06em;
  text-transform: uppercase;
}
html body #fnr-flow .ff-item.ff-back.sel .ff-pct,
html body #fnr-flow .ff-item.ff-back.sel .ff-name {
  color: #fff;
}
/* a pilula de vidro nao cobre a faixa */
html body #fnr-flow .ff-list:has(.ff-back.sel) .ff-lens {
  opacity: 0 !important;
}
/* com o dedo: sobe, de baixo para cima, até a altura e a cor do retangulo */
html body #fnr-flow .ff-item.ff-back::after {
  content: "";
  position: absolute;
  left: var(--bk-in);
  right: var(--bk-in);
  top: 4px;
  bottom: 4px;
  z-index: -1;
  box-sizing: border-box;
  border: 1px solid rgba(255,255,255,.22);
  border-radius: var(--bk-r);
  background: rgba(255,255,255,.08);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.16);
  clip-path: inset(100% 0 0 0 round var(--bk-r));
  transition: clip-path .18s ease;
  pointer-events: none;
}
html body #fnr-flow .ff-item.ff-back.sel::after {
  clip-path: inset(0 0 0 0 round var(--bk-r));
  transition: clip-path .35s cubic-bezier(.25,.9,.3,1);
}
@media (prefers-reduced-motion:reduce) {
  html body #fnr-flow .ff-item.ff-back::before { transition: none; }
}
@media (max-width:1200px) {
  html.fnr-flow #fnr-tipbox .ff-tip {
    color: #fff;
    text-shadow: none;
  }
  html.fnr-flow #fnr-tipbox .ff-tip svg {
    fill: #fff;
    filter: none;
  }
  html.fnr-flow #fnr-tipbox .ff-tip.on {
    visibility: visible;
    animation: ffTipFloat 2s ease-in-out infinite,ffTipIn .35s ease both;
  }
  html.fnr-flow #fnr-tipbox .ff-tip.out {
    visibility: visible;
    animation: ffTipFloat 2s ease-in-out infinite,ffTipOut .85s cubic-bezier(.22,1,.36,1) forwards;
  }
}
@media (prefers-reduced-motion:reduce) {
  html.fnr-flow #fnr-tipbox .ff-tip.on { animation: none; opacity: 1; }
  html.fnr-flow #fnr-tipbox .ff-tip.out { animation: none; }
}
/* ========================================================================
   34F. DESFOQUE LEVE (celular incluso) - DESLIGADO NO MODO ENERGIA
   A regra de desempenho do touch (secao 33) continua tirando o desfoque
   de tudo; aqui ele volta so em poucos elementos pequenos ou parados,
   com raio menor no celular. Com o modo energia ligado nada disso vale.
   ======================================================================== */
@media (hover:none) and (pointer:coarse) {
  /* balao "Ola, sou o Felipe..." */
  html:root:not(.fnr-lite) body .flpnr_tm_home .details .job {
    -webkit-backdrop-filter: blur(14px) !important;
    backdrop-filter: blur(14px) !important;
  }
  /* painel do menu flutuante (so aparece com o dedo parado na pilula) */
  html:root:not(.fnr-lite) body #fnr-flow .ff-panel {
    -webkit-backdrop-filter: blur(16px) !important;
    backdrop-filter: blur(16px) !important;
  }
}
/* botoes flutuantes (Modo leve, Musica): vidro escuro leve.
   desfoque e inversao de cor nao funcionam juntos no mesmo botao,
   entao com desfoque o fundo fica escuro translucido e o icone branco;
   no modo energia volta a inversao de cor, sem desfoque */
html:root:not(.fnr-lite) body #fnr-lite-btn,
html:root:not(.fnr-lite) body #fnr-float-icon {
  mix-blend-mode: normal;
  border: 1px solid rgba(255,255,255,.35) !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.30) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  backdrop-filter: blur(6px) !important;
}
html:root:not(.fnr-lite) body #fnr-lite-btn:not([aria-pressed="true"]),
html:root:not(.fnr-lite) body #fnr-float-icon:not(.playing) {
  background-color: rgba(20,20,28,.45) !important;
}
/* pilula do Menu do celular: mesmo vidro */
@media (max-width:1200px) {
  html:root:not(.fnr-lite) body #op-ruler {
    mix-blend-mode: normal;
  }
  html:root:not(.fnr-lite) body #op-ruler .opr-chip,
  html:root:not(.fnr-lite) body #op-ruler .opr-cur.ff-live .opr-chip {
    background-color: rgba(20,20,28,.45) !important;
    border: 1px solid rgba(255,255,255,.35) !important;
    box-shadow: 0 8px 24px rgba(0,0,0,.30) !important;
    -webkit-backdrop-filter: blur(6px) !important;
    backdrop-filter: blur(6px) !important;
  }
  /* dica "segure e arraste" acima da pilula continua invertendo a cor */
  html:root:not(.fnr-lite) body #op-ruler .ff-tip {
    mix-blend-mode: difference;
  }
}
/* modo energia no computador: sem desfoque no painel do menu */
html.fnr-lite body #fnr-flow .ff-panel {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
