/* ========================================================================
   36. TABLET (ATE 1200px): SEM EFEITOS DE HOVER, COMO NO CELULAR
   ======================================================================== */
@media (max-width:1200px) {
  .mouse-cursor { display: none !important; }
  body #fnr-sound-cursor, body #fnr-sound-tooltip { display: none !important; }

  /* cartoes de vidro, stories, galeria, miniaturas */
  html body .glass-card:hover { transform: none !important; border-color: rgba(255,255,255,.2) !important; box-shadow: 0 8px 32px 0 rgba(0,0,0,.3) !important; }
  html body .glass-card:hover::before { opacity: 0 !important; animation: none !important; }
  html body .story-card:hover { transform: none !important; }
  html body .story-card:hover::after { border-color: #56585c !important; }
  html body .flpnr_tm_portfolio .portfolio_list .inner:hover img,
  html body .flpnr_tm_portfolio .portfolio_list > div .inner:hover img { transform: none !important; filter: none !important; }
  html body .post-gallery a:hover img { transform: none !important; }
  html body .nn-thumb:hover { opacity: 1 !important; }
  html body .flpnr_tm_services .list .in-service .widget .list_inner:hover { border-color: #56585c !important; }
  html body .flpnr_tm_services .list .in-service .widget .list_inner:hover .number { background-color: rgba(255,255,255,.03) !important; }
  html body .flpnr_tm_news .index-post-wrap .index-post .list_inner:hover .image .main,
  html body .flpnr_tm_news .index-post-wrap .index-post .image:hover .main { transform: none !important; }
  html body .flpnr_tm_news .index-post-wrap .index-post .list_inner:hover .details { box-shadow: none !important; }
  html body .profile-pic-wrapper:hover .avatar .image { transform: none !important; box-shadow: none !important; }

  /* botoes de vidro: sem subida e sem brilho no hover */
  html:root body .flpnr_tm_button a:hover,
  html:root body .fnr_panel_btn:hover,
  html:root body input[type="submit"]:hover,
  html:root body .fnr-pj-btn:hover,
  html:root body .nn-btn-dl:hover { transform: none !important; }
  html:root body .flpnr_tm_button a:hover::before,
  html:root body .fnr_panel_btn:hover::before,
  html:root body .fnr-pj-btn:hover::before,
  html:root body .nn-btn-dl:hover::before,
  html:root body .vid-btn:hover::before,
  html:root body .char-btn:hover::before,
  html:root body .stories-arrow:hover::before,
  html:root body .gt-nav-btn:hover::before { animation: none !important; opacity: 0 !important; }
  html body .opensea-arrow:hover { transform: translateY(-50%) !important; }
  html body .opensea-arrow:hover ~ .in-fact .widget { transform: none !important; }

  /* Interesses: so colore ao tocar (.is-colored) */
  html body .flpnr_tm_interests .in-interests .widget a:not(.is-colored):hover .fnr-tri-video { filter: grayscale(1) contrast(1.15) brightness(.56) !important; }
  html body .flpnr_tm_interests .in-interests .widget a:not(.is-colored):hover::after { opacity: 1 !important; }
  .flpnr_tm_pricing .list_inner:hover .fnr-pv { filter: grayscale(1) contrast(1.15) brightness(.7) !important; }

  /* legendas dos projetos: sempre visiveis, como no celular */
  html body a.fnr-pj-open .fnr-pj-cap { opacity: 1 !important; transform: none !important; }
  /* cartoes da home e miniaturas de PDF: sem inclinacao 3D */
  html body .fnr_card,
  html body .nn-thumb,
  html body .nn-thumb.fnr-tilt {
    transform: none !important;
    box-shadow: none !important;
    will-change: auto !important;
  }
  html body .fnr_card { box-shadow: 0 0 0 1px rgba(255,255,255,.07), 0 28px 70px rgba(0,0,0,.5) !important; }
  html body .nn-thumb.fnr-tilt { z-index: auto !important; opacity: 1 !important; }
}

div.script:
/**/ (function timeAgo() {
  var meses = {
    'janeiro':0,'fevereiro':1,'mar\u00e7o':2,'abril':3,'maio':4,'junho':5,
    'julho':6,'agosto':7,'setembro':8,'outubro':9,'novembro':10,'dezembro':11
  };
  var templates = {
    prefix: "",
    suffix: " atr\u00e1s",
    seconds: "Alguns segundos",
    minute: "Um minuto",
    minutes: "%d min",
    hour: "Uma hora",
    hours: "%d horas",
    day: "Um dia",
    days: "%d dias",
    month: "Um m\u00eas",
    months: "%d meses",
    year: "Um ano",
    years: "%d anos"
  };
  var template = function(t, n) {
    return templates[t] && templates[t].replace(/%d/i, Math.abs(Math.round(n)));
  };
  var parseBR = function(str) {
    var m = str.match(/(\d+)\s+de\s+(\w+)\s+de\s+(\d{4})\s+\u00e0s\s+(\d+):(\d+)/i);
    if (m) {
      var mes = meses[m[2].toLowerCase()];
      if (mes !== undefined) {
        return new Date(parseInt(m[3]), mes, parseInt(m[1]), parseInt(m[4]), parseInt(m[5]), 0);
      }
    }
    return new Date(str);
  };
  var timer = function(str) {
    if (!str) return;
    var time = parseBR(str);
    if (isNaN(time.getTime())) return;
    var now = new Date();
    var seconds = ((now.getTime() - time.getTime()) * .001) >> 0;
    var minutes = seconds / 60;
    var hours = minutes / 60;
    var days = hours / 24;
    var years = days / 365;
    return templates.prefix + (
      seconds < 45 && template('seconds', seconds) ||
      seconds < 90 && template('minute', 1) ||
      minutes < 45 && template('minutes', minutes) ||
      minutes < 90 && template('hour', 1) ||
      hours < 24 && template('hours', hours) ||
      hours < 42 && template('day', 1) ||
      days < 30 && template('days', days) ||
      days < 45 && template('month', 1) ||
      days < 365 && template('months', days / 30) ||
      years < 1.5 && template('year', 1) ||
      template('years', years)
    ) + templates.suffix;
  };
  var elements = document.getElementsByClassName('datetime');
  for (var i = 0; i < elements.length; i++) {
    var el = elements[i];
    if (typeof el === 'object') {
      var result = timer(el.getAttribute('title') || el.getAttribute('data-datetime'));
      if (result) el.innerHTML = result;
    }
  }
  setTimeout(timeAgo, 60000);
})(); /**/

body.script:
//
(function () {
  if (window.__fnrFrame) { return; }
  var reads = {}, keys = [], deferred = [], raf = 0, flushing = false;
  function flush() {
    raf = 0; flushing = true;
    var ks = keys, rs = reads, ws = [], i, w;
    keys = []; reads = {};
    try {
      for (i = 0; i < ks.length; i++) {            /* 1) todas as leituras de layout */
        try { w = rs[ks[i]](); if (typeof w === "function") { ws.push(w); } } catch (e) {}
      }
      ws = ws.concat(deferred); deferred = [];
    } finally { flushing = false; }
    for (i = 0; i < ws.length; i++) {              /* 2) depois todas as escritas */
      try { ws[i](); } catch (e) {}
    }
  }
  window.__fnrFrame = {
    /* queue(chave, leitura): a leitura le o layout e pode devolver uma funcao de escrita */
    queue: function (key, fn) {
      if (!Object.prototype.hasOwnProperty.call(reads, key)) { keys.push(key); }
      reads[key] = fn;
