function flpnr_tm_trigger_menu() {
  jQuery(document).on("click touchstart", function (e) {
    var menu    = jQuery(".flpnr_tm_mobile_menu");
    var trigger = jQuery(".flpnr_tm_topbar .trigger .hamburger");
    if (
      menu.hasClass("opened") &&
      !jQuery(e.target).closest(".flpnr_tm_mobile_menu").length &&
      !jQuery(e.target).closest(".flpnr_tm_topbar .trigger").length
    ) {
      trigger.removeClass("is-active");
      menu.removeClass("opened");
    }
  });

  var hamburger = jQuery(".flpnr_tm_topbar .trigger .hamburger");
  var mobileMenu = jQuery(".flpnr_tm_mobile_menu");
  var mobileLinks = jQuery(".flpnr_tm_mobile_menu ul li a");

  hamburger.on("click", function () {
    var btn = jQuery(this);
    if (btn.hasClass("is-active")) {
      btn.removeClass("is-active");
      mobileMenu.removeClass("opened");
    } else {
      btn.addClass("is-active");
      mobileMenu.addClass("opened");
    }
    return false;
  });

  mobileLinks.on("click", function () {
    jQuery(".flpnr_tm_topbar .trigger .hamburger").removeClass("is-active");
    mobileMenu.removeClass("opened");
  });
}

function flpnr_tm_modalbox() {
