  document.addEventListener("visibilitychange", function () { if (document.hidden && active) { finish(null, true); } });

  root.classList.add("fnr-flow");   
}

function flpnr_tm_service_popup() {
  var modalbox  = jQuery(".flpnr_tm_modalbox");
  var triggers  = jQuery(".flpnr_tm_services .flpnr_tm_full_link");
  var closeBtn  = modalbox.find(".close");
  var slugAtual = null;
  var mousedownNoFundo = false;

  function slugify(texto) {
    return String(texto || "")
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      .toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  }
  function widgetDe(el) {
    return jQuery(el).closest(".flpnr_tm_services .list .in-service .widget");
  }
  function slugDe(el) {
    return slugify(widgetDe(el).find(".title").first().text());
  }
  function secaoDe(el) {
    return jQuery(el).closest(".flpnr_tm_section").attr("id") || "";
  }

  function mostrar(el) {
    var widget  = widgetDe(el);
    var imgSrc  = widget.find(".popup_service_image").attr("src");
    var title   = widget.find(".title").text();
    var content = widget.find(".service_hidden_details").html();

    modalbox.addClass("opened");
    modalbox.find(".description_wrap").html(content);
    modalbox.find(".service_popup_informations").prepend(
      '<div class="image"><img loading="lazy" decoding="async" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjTV9CrlZyqQ_sJd42umSz-DEsWJocx1gPCNaTwuwDiEHkCzrUPqV4zQmbOa4jaX6PiSl8tf0L49E23yi_fh4IpoTGsK-Q6LhR8luxTYBN9eZrPEJM332MDyk7P3bb-s7BKh7LKyXTL6u48G-tabPpDhSWGFt_kxsR3K6Q2_-IWi6Ge5ZxGGB_Oh1YR2g/s0/4-2.jpg" alt="" /><div class="main" data-img-url="' +
        imgSrc + '"></div></div>'
    );
    flpnr_tm_data_images();
    modalbox.find(".service_popup_informations .image").after(
      '<div class="main_title"><h3>' + title + "</h3></div>"
    );
  }

  function abrir(el) {
    var slug = slugDe(el);
    var secao = secaoDe(el);
    mostrar(el);
    if (slug && secao) {
      slugAtual = slug;
      history.pushState({ flpnrPopup: true }, "", __fnrRoute.url(slug));
    }
  }

  function fechar(mudarUrl) {
    modalbox.removeClass("opened");
    modalbox.find(".description_wrap").html("");
    if (slugAtual) {
      slugAtual = null;
      if (mudarUrl) {
        if (history.state && history.state.flpnrPopup) {
          history.back();
        } else {
          history.replaceState(null, "", __fnrRoute.closeUrl());
        }
      }
    }
  }

  function sincronizar() {
    var slug = __fnrRoute.slug();
    var partes = [""];
    var antigo = false;
    if (!slug) {
      if (slugAtual) { fechar(false); }
      return;
    }
    if (slug === slugAtual) { return; }
    var achado = null;
    triggers.each(function () {
      if (slugDe(this) !== slug) { return; }
      if (antigo && secaoDe(this) !== partes[0]) { return; }
      var visivel = !jQuery(this).closest(".flpnr_tm_section").hasClass("hidden");
      if (!achado || visivel) { achado = this; }
      if (visivel) { return false; }
    });
    if (achado) {
      mostrar(achado);
      slugAtual = slug;

    } else if (slugAtual) {
      fechar(false);
    }
  }

  triggers.on("click", function () {
    abrir(this);
    return false;
  });

  closeBtn.on("click", function () {
    fechar(true);
    return false;
  });

  modalbox.on("mousedown touchstart", function (e) {
    mousedownNoFundo = (e.target === this);
  });
  modalbox.on("click", function (e) {
    if (e.target === this && mousedownNoFundo) {
      closeBtn.trigger("click");
    }
    mousedownNoFundo = false;
  });

  jQuery(window).on("popstate", sincronizar);
  sincronizar();
}

function flpnr_tm_modalbox_news() {
  var modalbox = jQuery(".flpnr_tm_modalbox");
