function flpnr_tm_projects() {
  jQuery(".flpnr_tm_portfolio_animation_wrap").each(function () {
    jQuery(this)
      .on("mouseenter", function () {
        if (window.matchMedia("(max-width: 1200px), (hover: none)").matches) {
          return;
        }
        if (jQuery(this).data("title")) {

          var img = jQuery(this).data("image") ? '<img src="' + jQuery(this).data("image") + '" style="max-width:243px; display:block; margin-bottom:8px; margin-top:8px;" />' : '';

          var limiteCaracteres = 35;
          var catTexto = String(jQuery(this).data("category") || "");

          if (catTexto.length > limiteCaracteres) {
              catTexto = catTexto.substring(0, limiteCaracteres) + "...";
          }

          jQuery(".flpnr_tm_portfolio_titles").html(
            img +
            jQuery(this).data("title") +
              '<span class="work__cat">' +
              catTexto +
              "</span>"
          );
          jQuery(".flpnr_tm_portfolio_titles").addClass("visible");
        }
        jQuery(document).on("mousemove", function (e) {
          if (jQuery(".flpnr_tm_portfolio_titles").length === 0) return;
          jQuery(".flpnr_tm_portfolio_titles").css({
            left: e.clientX - 10,
            top:  e.clientY + 25
          });
        });
      })
      .on("mouseleave", function () {
        jQuery(".flpnr_tm_portfolio_titles").removeClass("visible");
      });
  });
}

function flpnr_tm_my_progress() {
  var duracao = 2600;
  var atraso  = 520;
  var repetir = true;
  var itens   = jQuery(".flpnr_progress .progress_inner");
  var reduzir = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function ease(t) { return 1 - Math.pow(1 - t, 3); }

  function desenhar(inner, v) {
    inner.find(".bar_in").css("width", v + "%");
    inner.find(".number").text(Math.round(v) + "%");
  }

  function zerar(inner) {
    inner.data("token", (inner.data("token") || 0) + 1);
    inner.data("estado", "zero");
    desenhar(inner, 0);
  }

  function animar(inner, ordem) {
    var alvo  = parseFloat(inner.data("value")) || 0;
    var token = (inner.data("token") || 0) + 1;
    inner.data("token", token);
    inner.data("estado", "ativa");
    if (reduzir) { desenhar(inner, alvo); return; }
    setTimeout(function () {
      var inicio = null;
      function passo(agora) {
        if (inner.data("token") !== token) return;
        if (inicio === null) inicio = agora;
        var t = Math.min((agora - inicio) / duracao, 1);
        desenhar(inner, alvo * ease(t));
        if (t < 1) requestAnimationFrame(passo);
      }
      requestAnimationFrame(passo);
    }, ordem * atraso);
  }

  var FR = window.__fnrFrame || { queue: function (k, f) { requestAnimationFrame(function () { var w = f(); if (w) { w(); } }); }, defer: function (f) { f(); } };
  function verificarLer() {                 /* fase de leitura: so decide o que fazer */
    var h = window.innerHeight, acoes = [];
    itens.each(function () {
      var inner   = jQuery(this);
      var secao   = inner.closest(".flpnr_tm_section");
      var aberta  = !secao.length || secao.hasClass("active");
      var r       = this.getBoundingClientRect();
      var visivel = aberta && r.top < h * 0.92 && r.bottom > 0;
      var estado  = inner.data("estado");
      if (visivel && estado !== "ativa") acoes.push([inner, 1]);
      else if (!aberta && repetir && estado === "ativa") acoes.push([inner, 0]);
    });
    if (!acoes.length) return null;
    return function () {                    /* fase de escrita */
      var ordem = 0;
      for (var i = 0; i < acoes.length; i++) {
        if (acoes[i][1]) animar(acoes[i][0], ordem++); else zerar(acoes[i][0]);
      }
    };
  }
  function verificar() { var w = verificarLer(); if (w) w(); }

  var pendente = false;
  function agendar() {
    if (pendente) return;
    pendente = true;
    FR.queue("verificar", function () { pendente = false; return verificarLer(); });
  }

  itens.each(function () { zerar(jQuery(this)); });
  document.addEventListener("scroll", agendar, { capture: true, passive: true });
  jQuery(window).on("resize", agendar);
  jQuery(".transition_link a").on("click", function () {
    setTimeout(verificar, 150);
    setTimeout(verificar, 700);
  });
  setTimeout(verificar, 300);
}

function flpnr_tm_preloader() {
