  }, 500);
}

function flpnr_tm_cursor() {
  var cursors = jQuery(".mouse-cursor");
  if (cursors.length) {
    if ($("body")) {
      var inner = document.querySelector(".cursor-inner");
      var outer = document.querySelector(".cursor-outer");

      window.onmousemove = function (e) {
        if (window.__fnrLite) return;
        outer.style.transform = "translate(" + e.clientX + "px, " + e.clientY + "px)";
        inner.style.transform = "translate(" + e.clientX + "px, " + e.clientY + "px)";
      };

      $("body").on("mouseenter", "a, .cursor-pointer", function () {
        inner.classList.add("cursor-hover");
        outer.classList.add("cursor-hover");
      });

      $("body").on("mouseleave", "a, .cursor-pointer", function () {
        if (!($(this).is("a") && $(this).closest(".cursor-pointer").length)) {
          inner.classList.remove("cursor-hover");
          outer.classList.remove("cursor-hover");
        }
      });

      inner.style.visibility = "visible";
      outer.style.visibility = "visible";
    }
  }
}

function flpnr_tm_imgtosvg() {
  jQuery("img.svg").each(function () {
    var img      = jQuery(this);
    var imgClass = img.attr("class");
    var imgSrc   = img.attr("src");

    jQuery.get(imgSrc, function (data) {
      var svg = jQuery(data).find("svg");
      if (typeof imgClass !== "undefined") {
        svg = svg.attr("class", imgClass + " replaced-svg");
      }
      svg = svg.removeAttr("xmlns:a");
      img.replaceWith(svg);
    }, "xml");
  });
}

function flpnr_tm_popup() {
  jQuery(".gallery_zoom").each(function () {
    jQuery(this).magnificPopup({
      delegate:     "a.zoom",
      type:         "image",
      gallery:      { enabled: true },
      removalDelay: 300,
      mainClass:    "mfp-fade"
    });
  });

  jQuery(".popup-youtube, .popup-vimeo").each(function () {
    jQuery(this).magnificPopup({
      disableOn:       700,
      type:            "iframe",
      mainClass:       "mfp-fade",
      removalDelay:    160,
      preloader:       false,
      fixedContentPos: false
    });
  });

  jQuery(".soundcloude_link").magnificPopup({
    type:    "image",
    gallery: { enabled: true }
  });

  /* video da Galeria: o player e montado no toque e o play() e chamado
     dentro do proprio toque (o iPhone bloqueia autoplay em alguns casos,
     ex. modo de pouca energia). Ao fechar, o video e descarregado */
  jQuery(".popup-mp4").on("click", function (e) {
    e.preventDefault();
    var url = this.getAttribute("href");
    var box = document.createElement("div");
    box.className = "flpnr-mp4-popup";
    box.style.cssText = "background:#000;max-width:900px;width:90vw;margin:40px auto;position:relative;border-radius:4px;overflow:hidden;";
    var v = document.createElement("video");
    v.controls = true;
    v.muted = true;
    v.defaultMuted = true;
    v.playsInline = true;
    v.setAttribute("muted", "");
    v.setAttribute("playsinline", "");
    v.setAttribute("webkit-playsinline", "");
    v.preload = "auto";
    v.style.cssText = "width:100%;display:block;max-height:80vh;background:#000;";
    var src = document.createElement("source");
    src.src = url;
    src.type = "video/mp4";
    v.appendChild(src);
    box.appendChild(v);
    jQuery.magnificPopup.open({
      items: { src: jQuery(box), type: "inline" },
      mainClass: "mfp-fade",
      removalDelay: 160,
      closeBtnInside: true,
      callbacks: {
        open: function () {
          var p = v.play();
          if (p && p.catch) p.catch(function () {});
        },
        close: function () {
          try { v.pause(); } catch (x) {}
          while (v.firstChild) v.removeChild(v.firstChild);
          v.removeAttribute("src");
          try { v.load(); } catch (x) {}
        }
      }
    });
  });
}

function flpnr_tm_data_images() {
