    var imgUrl = el.data("img-url");
    el.css({ backgroundImage: "url(" + imgUrl + ")" });
  });
}

function flpnr_tm_owl_carousel() {
  var $c = jQuery(".flpnr_tm_testimonials .owl-carousel");
  if (!$c.length || $c.hasClass("owl-loaded")) return;

  $c.owlCarousel({
    loop:            true,
    items:           2,
    lazyLoad:        false,
    margin:          30,
    autoplay:        true,
    autoplayTimeout: 7000,
    autoplaySpeed:   700,
    smartSpeed:      700,
    navSpeed:        700,
    autoplayHoverPause: true,
    dots:            false,
    nav:             false,
    responsiveRefreshRate: 100,
    responsive: {
      0:   { items: 1 },
      768: { items: 2 }
    }
  });

  var $list = $c.closest(".list");

  function chev(d) {
    return '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="' + d +
           '" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="square" stroke-linejoin="miter"/></svg>';
  }
  if (!$list.parent().hasClass("tst_wrap")) {
    $list.wrap('<div class="tst_wrap"></div>');
    $list.before(
      '<button type="button" class="tst_arrow tst_prev cursor-pointer" aria-label="Depoimento anterior">' + chev("M15 4L7 12l8 8") + '</button>' +
      '<button type="button" class="tst_arrow tst_next cursor-pointer" aria-label="Pr\u00f3ximo depoimento">' + chev("M9 4l8 8-8 8") + '</button>'
    );
  }
  var $wrap = $list.parent();
  var navLock = false;
  function go(dir) {
    if (navLock) return;
    navLock = true;
    setTimeout(function () { navLock = false; }, 350);
    $c.trigger(dir + ".owl.carousel", [600]);
    $c.trigger("stop.owl.autoplay");
    $c.trigger("play.owl.autoplay", [7000]);
  }
  $wrap.on("click", ".tst_prev", function (e) { e.preventDefault(); go("prev"); });
  $wrap.on("click", ".tst_next", function (e) { e.preventDefault(); go("next"); });

  function placeArrows() {
    var $a = $wrap.find(".tst_arrow");
    if (window.innerWidth <= 1040) { $a.css({ top: "", marginTop: "" }); return; }
    var h = 0;
    $c.find(".owl-item .text").each(function () {
      h = Math.max(h, jQuery(this).outerHeight() || 0);
    });
    if (h) $a.css({ top: Math.round(h / 2) + "px", marginTop: "-16px" });
  }

  var lastW = 0, timer = null;
  function refresh(force) {
    var w = $list.width();
    if (w && (force === true || w !== lastW)) {
      lastW = w;
      $c.trigger("refresh.owl.carousel");
    }
    placeArrows();
  }
  function refreshSoon() {
    clearTimeout(timer);
    timer = setTimeout(function () { refresh(); }, 80);
  }

  refreshSoon();
  setTimeout(function () { refresh(true); }, 400);
  setTimeout(function () { refresh(true); }, 1200);
  setTimeout(function () { refresh(true); }, 2500);
  jQuery(window).on("load resize orientationchange", refreshSoon);
  if (window.ResizeObserver && $list[0]) {
    new ResizeObserver(refreshSoon).observe($list[0]);
  }
  jQuery(".transition_link a").on("click", function () {
    setTimeout(function () { refresh(true); }, 100);
    setTimeout(function () { refresh(true); }, 1100);
  });
}

