window.__fnrLazyInit = function (el, fn, timeout) {
  var done = false;
  function run() { if (done) return; done = true; try { fn(); } catch (e) { if (window.console) console.error(e); } }
  function idle() {
    if ('requestIdleCallback' in window) requestIdleCallback(run, { timeout: timeout || 2000 });
    else setTimeout(run, 200);
  }
  if (!el || !('IntersectionObserver' in window)) { idle(); return; }
  var io = new IntersectionObserver(function (entries) {
    for (var i = 0; i < entries.length; i++) {
      if (entries[i].isIntersecting) { io.disconnect(); idle(); return; }
    }
  }, { rootMargin: '200px 0px 200px 0px' });
  io.observe(el);
};
