  var BOX = '.blogComments .commentFlex,#threaded-comment-form,' +
    '.flpnr_tm_all_wrap .leftpart,.flpnr_tm_news .index-post-wrap .index-post .details,' +
    '.flpnr_tm_progressbox,.flpnr_tm_resumebox,.flpnr_tm_partners,' +
    '.flpnr_tm_pricing,#apps,.os-panel.is-on';
