  /* LEITURA: uma unica passada de getBoundingClientRect por frame; devolve a escrita so se algo mudou */
  function clipRead() {
    clipRaf = 0;
    var vw = Math.max(W, window.innerWidth), vh = Math.max(H, window.innerHeight), q = window.devicePixelRatio || 1;
    var rects = [], key = '', i, r;
