    if (key === clipKey) return null;                          /* retangulos iguais: nao remonta o path */
    clipKey = key;
    var d = '';
    for (i = 0; i < rects.length; i += 5) { d += rectPath(rects[i], rects[i + 1], rects[i + 2], rects[i + 3], vw, vh); }
