document.addEventListener('DOMContentLoaded', function () {
(function() {


  var BPM        = 80;  
  var BOOST      = 8;  
  var WAVE       = 3.0;  
  var LERP_IN    = 0.1; 
  var LERP_OUT   = 0.06; 


  var isHome  = false;
  var rafId   = null;
  var started = false;

  function checkHome() {
    var h = document.getElementById('home');
    if (!h) { isHome = false; return; }
    if (document.documentElement.classList.contains('spa-booting')) { isHome = false; return; }
    if (document.body && document.body.classList.contains('spa-on-page')) { isHome = false; return; }
    var path = location.pathname.replace(/^\/+|\/+$/g, '').split('/')[0];
    if (/^(3d|id|projetos|designer-pleno|fotos|producao|perfil|portfolio|galeria|apps|blog)$/i.test(path)) { isHome = false; return; }
    var id = location.hash.replace('#', '').split('/')[0];
    if (id && id !== 'home') {
      var t = document.getElementById(id);
      if (t && t.classList.contains('flpnr_tm_section')) { isHome = false; return; }
    }
    isHome = !h.classList.contains('hidden') && window.__fnrHomeActive !== false;
  }

  function wiggle(ts) {
    rafId = requestAnimationFrame(wiggle);
    if (window.__fnrLite) return; 
    var pJS = window.pJSDom && window.pJSDom[0] && window.pJSDom[0].pJS;
    if (!pJS || !pJS.particles || !pJS.particles.array) return;
    var arr = pJS.particles.array;

    if (!isHome) {
      arr.forEach(function(p) {
        if (!p._vx0) return;
        p.vx += (p._vx0 - p.vx) * LERP_OUT;
        p.vy += (p._vy0 - p.vy) * LERP_OUT;
      });
      return;
    }

    var t        = ts * 0.001;
    var beat     = (BPM / 60) * 2 * Math.PI;
    var bass     = Math.sin(t * beat);
    var mid      = Math.sin(t * beat * 2 + 1.2);
    var hi       = Math.sin(t * beat * 4 + 2.4);
    var kick     = Math.abs(Math.sin(t * beat * 0.5));
    var envelope = 1 + (BOOST - 1) * kick * Math.abs(bass);

    arr.forEach(function(p, i) {
      if (!p._vx0) return;
      var phase    = (i % 6) * (Math.PI / 3);
      var waveX    = WAVE * (bass * Math.cos(phase) + mid * Math.sin(phase) * 0.5);
      var waveY    = WAVE * (mid  * Math.cos(phase) - hi  * Math.sin(phase) * 0.3);
      var targetVx = p._vx0 * (envelope + waveX);
      var targetVy = p._vy0 * (envelope + waveY);
      p.vx += (targetVx - p.vx) * LERP_IN;
      p.vy += (targetVy - p.vy) * LERP_IN;
    });
  }

  function init() {
    if (started) return;
    var pJS = window.pJSDom && window.pJSDom[0] && window.pJSDom[0].pJS;
    if (!pJS || !pJS.particles || !pJS.particles.array || pJS.particles.array.length === 0) return;
    started = true;

    pJS.particles.array.forEach(function(p) {
      p._vx0 = p.vx || (Math.random() - 0.5) * 0.8;
      p._vy0 = p.vy || (Math.random() - 0.5) * 0.8;
    });

    checkHome();

    var sections = document.querySelectorAll('.flpnr_tm_section');
    var mo = new MutationObserver(checkHome);
    sections.forEach(function(s) {
      mo.observe(s, { attributes: true, attributeFilter: ['class'] });
    });

    document.querySelectorAll('.leftpart .menu ul li a, .flpnr_tm_mobile_menu .menu_list ul li a')
      .forEach(function(link) {
        link.addEventListener('click', function() {
          var href = link.getAttribute('href') || '';
          isHome = (href === '#home');
        });
      });

    window.addEventListener('hashchange', checkHome);
    window.addEventListener('popstate', checkHome);

    window.addEventListener('fnr:homeactive', function (ev) {
      var on = !!(ev && ev.detail && ev.detail.on);
      isHome = on && !(document.body && document.body.classList.contains('spa-on-page'));
    });

    rafId = requestAnimationFrame(wiggle);
  }

  var tryInit = setInterval(function() {
    init();
    if (started) clearInterval(tryInit);
  }, 150);

  setTimeout(function() { clearInterval(tryInit); }, 15000);

  window.addEventListener('fnr:particlesready', function () { init(); });

})();
});
