(function () {
  var h3  = document.getElementById('fnr-title-h3');
  var txt = document.getElementById('fnr-title-text');
  if (!h3 || !txt) return;

  var ALT = 'Designer, 3D\ne Motion';
  var DELETE_SPEED = 22;   
  var TYPE_SPEED   = 22;   

  var original = txt.textContent.trim();
  var current  = original;
  var target   = original;
  var timer    = null;
  var locked   = false;

  var mq = window.matchMedia('(min-width: 1041px) and (hover: hover) and (pointer: fine)');

  function lock() {
    if (locked) return;
    var r = h3.getBoundingClientRect();
    h3.style.minWidth  = r.width + 'px';
    h3.style.minHeight = r.height + 'px';
    locked = true;
  }
  function unlock() {
    h3.style.minWidth = '';
    h3.style.minHeight = '';
    locked = false;
  }

  function syncAlt() {
    h3.classList.toggle('fnr-alt', current.length > 0 && ALT.indexOf(current) === 0);
  }

  function step() {
    if (current === target) {
      syncAlt();
      timer = null;
      h3.classList.remove('fnr-typing');
      if (current === original) unlock();
      return;
    }
    if (target.indexOf(current) !== 0) {
      current = current.slice(0, -1);                    
      txt.textContent = current;
      syncAlt();
      timer = setTimeout(step, DELETE_SPEED);
    } else {
      current = target.slice(0, current.length + 1);     
      txt.textContent = current;
      syncAlt();
      timer = setTimeout(step, TYPE_SPEED);
    }
  }

  function go(next) {
    target = next;
    if (timer === null) {
      h3.classList.add('fnr-typing');
      timer = setTimeout(step, 0);
    }
  }

  function reset() {
    clearTimeout(timer);
    timer = null;
    current = target = original;
    txt.textContent = original;
    h3.classList.remove('fnr-typing');
    h3.classList.remove('fnr-alt');
    unlock();
  }

  h3.addEventListener('mouseenter', function () {
    if (!mq.matches || !h3.getClientRects().length) return;
    lock();
    go(ALT);
  });

  h3.addEventListener('mouseleave', function () {
    if (current === original && timer === null) return;
    go(original);
  });

  var onChange = function () { if (!mq.matches) reset(); };
  if (mq.addEventListener) mq.addEventListener('change', onChange);
  else if (mq.addListener) mq.addListener(onChange);
})();
