body.script:
//
(function() {
  if (!document.getElementById('orbitCanvas') ||
      !document.getElementById('profile-container')) return;

  const ORBIT_RADIUS_PX  = 148;
  const ORBIT_RADIUS_CVS = 148;
  const PHOTO_BG         = 'data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 width=%276%27 height=%276%27%3E%3Ccircle cx=%27.9%27 cy=%27.7%27 r=%27.85%27 fill=%27white%27 fill-opacity=%27.17%27/%3E%3C/svg%3E';
  const NUM_ITEMS        = 6;
  const START_ANGLE_DEG  = -90;

  const container  = document.getElementById('profile-container');
  const photoWrap  = document.getElementById('main-photo-container');
  const canvas     = document.getElementById('orbitCanvas');
  const ctx        = canvas.getContext('2d');
  const items      = Array.from({ length: NUM_ITEMS }, (_, i) => document.getElementById('orbit-' + i));

  items.forEach(item => {
    const a = item.querySelector('a');
    if (a) a.style.backgroundImage = `url('${PHOTO_BG}')`;
  });

  let menuOpen    = false;
  let menuVisible = false;
  let animRaf     = null;

  function getCanvasPositions() {
    const cx = canvas.width / 2;
    const cy = canvas.height / 2;
    return Array.from({ length: NUM_ITEMS }, (_, i) => {
      const angle = (START_ANGLE_DEG + (360 / NUM_ITEMS) * i) * Math.PI / 180;
      return { x: cx + Math.cos(angle) * ORBIT_RADIUS_CVS, y: cy + Math.sin(angle) * ORBIT_RADIUS_CVS };
    });
  }

  function getScreenPositions() {
    return Array.from({ length: NUM_ITEMS }, (_, i) => {
      const angle = (START_ANGLE_DEG + (360 / NUM_ITEMS) * i) * Math.PI / 180;
      return { dx: Math.cos(angle) * ORBIT_RADIUS_PX, dy: Math.sin(angle) * ORBIT_RADIUS_PX };
    });
  }

  function showMenu() {
    if (menuVisible) return;
    menuVisible = true;
    canvas.classList.add('visible');
    const pos = getScreenPositions();
    items.forEach((item, i) => {
      item.style.transitionDelay = (i * 0.055) + 's';
      item.style.transform = `translate(${pos[i].dx}px, ${pos[i].dy}px) scale(1)`;
      item.classList.add('visible');
    });
    networkTarget = 1;
    if (!animRaf) animLoop();
  }

  function hideMenu() {
    if (!menuVisible) return;
    menuVisible = false;
    canvas.classList.remove('visible');
    items.forEach((item, i) => {
      item.style.transitionDelay = ((NUM_ITEMS - 1 - i) * 0.04) + 's';
      item.style.transform = `translate(0px, 0px) scale(0.2)`;
      item.classList.remove('visible');
    });
    setTimeout(() => { if (!menuVisible) networkTarget = 0; }, 600);
  }

  const W = canvas.width, H = canvas.height;
  const particles = Array.from({ length: 38 }, () => ({
    x: Math.random() * W, y: Math.random() * H,
    vx: (Math.random() - 0.5) * 0.6, vy: (Math.random() - 0.5) * 0.6,
    r: Math.random() * 2.5 + 1,
  }));

  let mouse = { x: W / 2, y: H / 2, active: false };

  function drawNetwork(alpha) {
    ctx.clearRect(0, 0, W, H);
    const cvPos = getCanvasPositions();
    const cx = W / 2, cy = H / 2;
    const nodes = [...particles, { x: cx, y: cy }, ...cvPos, ...(mouse.active ? [{ x: mouse.x, y: mouse.y }] : [])];

    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const dx = nodes[i].x - nodes[j].x;
        const dy = nodes[i].y - nodes[j].y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const maxDist = (i >= particles.length || j >= particles.length) ? 210 : 115;
        if (dist < maxDist) {
          ctx.beginPath();
          ctx.moveTo(nodes[i].x, nodes[i].y);
          ctx.lineTo(nodes[j].x, nodes[j].y);
          const lineAlpha = (1 - dist / maxDist) * 0.55 * alpha;
          ctx.strokeStyle = `rgba(255,255,255,${lineAlpha})`;
          ctx.lineWidth = 0.8;
          ctx.stroke();
        }
      }
    }

    particles.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(255,255,255,${0.3 * alpha})`;
      ctx.fill();
    });

    cvPos.forEach(pos => {
      ctx.beginPath();
      ctx.arc(pos.x, pos.y, 3.5, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(255,255,255,${0.4 * alpha})`;
      ctx.fill();
    });

    ctx.beginPath();
    ctx.arc(cx, cy, 4, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255,255,255,${0.3 * alpha})`;
    ctx.fill();
  }

  let networkAlpha = 0, networkTarget = 0;

  function animLoop() {
    particles.forEach(p => {
      p.x += p.vx; p.y += p.vy;
      if (p.x < 0 || p.x > W) p.vx *= -1;
      if (p.y < 0 || p.y > H) p.vy *= -1;
    });
    networkAlpha += (networkTarget - networkAlpha) * 0.06;
    if (networkAlpha > 0.005) drawNetwork(networkAlpha);
    else ctx.clearRect(0, 0, W, H);
    if (networkAlpha > 0.005 || networkTarget > 0) animRaf = requestAnimationFrame(animLoop);
    else animRaf = null;
  }

  photoWrap.addEventListener('click', (e) => {
    e.stopPropagation();
    menuOpen = !menuOpen;
    photoWrap.classList.toggle('menu-locked', menuOpen);
    if (menuOpen) showMenu(); else hideMenu();
    const hint = document.getElementById('fnr-tap-hint');
    if (hint) {
      hint.classList.add('hidden');
      const removeHint = () => { if (hint.parentNode) hint.parentNode.removeChild(hint); };
      hint.addEventListener('animationend', (ev) => {
        if (ev.animationName === 'hint-fadeout' || ev.animationName === 'hint-fadeout-simple') removeHint();
      });
      setTimeout(removeHint, 1200);
    }
  });

  document.addEventListener('click', (e) => {
    if (menuOpen && !container.contains(e.target)) {
      menuOpen = false;
      photoWrap.classList.remove('menu-locked');
      hideMenu();
    }
  });

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    mouse.x = (e.clientX - rect.left) * (canvas.width / rect.width);
    mouse.y = (e.clientY - rect.top) * (canvas.height / rect.height);
    mouse.active = true;
  });
  canvas.addEventListener('mouseleave', () => { mouse.active = false; });

})();
