//
  function calcularIdade() {
    const nascimento = new Date(1995, 2, 10);
    const hoje = new Date();

    let idade = hoje.getFullYear() - nascimento.getFullYear();
    const aniversarioPassou =
      hoje.getMonth() > nascimento.getMonth() ||
      (hoje.getMonth() === nascimento.getMonth() && hoje.getDate() >= nascimento.getDate());

    if (!aniversarioPassou) idade--;
    return idade;
  }

  document.querySelectorAll(".widget li, .widget span, .widget td").forEach(el => {
    if (el.childNodes.length === 1 && el.textContent.trim() === "00") {
      el.textContent = calcularIdade();
    }
  });
