(function () {
  'use strict';

  var KEY  = 'fnr-lite';                       
  var root = document.documentElement;
  var btn  = document.getElementById('fnr-lite-btn');
  var lbl  = document.getElementById('fnr-lite-label');
  if (!btn) return;

  function getPJS() {
    return window.pJSDom && window.pJSDom[0] && window.pJSDom[0].pJS;
  }
  function freezeParticles() {
    var p = getPJS();
    try { if (p && p.fn) cancelAnimationFrame(p.fn.drawAnimFrame); } catch (e) {}
  }
  function resumeParticles() {
    var p = getPJS();
    try {
      if (p && p.fn && p.fn.vendors && p.fn.vendors.draw) {
        cancelAnimationFrame(p.fn.drawAnimFrame);
        p.fn.vendors.draw();
      }
    } catch (e) {}
  }

  function readPref()  { try { return localStorage.getItem(KEY); } catch (e) { return null; } }
  function savePref(v) { try { localStorage.setItem(KEY, v); } catch (e) {} }

  var current = false;

  function syncUI() {
    btn.setAttribute('aria-pressed', current ? 'true' : 'false');
    btn.setAttribute('aria-label', current
      ? 'Modo leve ligado: tocar para reativar as animações de fundo'
      : 'Modo leve desligado: tocar para desativar as animações de fundo');
    lbl.textContent = current ? 'performance' : 'fidelidade';
  }

  function apply(on) {
    if (on === current) { syncUI(); return; }
    current = on;
    window.__fnrLite = on;
    root.classList.toggle('fnr-lite', on);
    if (on) freezeParticles(); else resumeParticles();
    syncUI();
    try { window.dispatchEvent(new CustomEvent('fnr:lite', { detail: { on: on } })); } catch (e) {}
  }

  var saved = readPref();
  var conn  = navigator.connection || {};
  var auto  = (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) || conn.saveData === true; /* so liga sozinho por ajuste do sistema */
  apply(saved === null ? auto : saved === '1');

  var toastTimer;
  btn.addEventListener('click', function () {
    var next = !current;
    savePref(next ? '1' : '0');
    apply(next);
    lbl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { lbl.classList.remove('show'); }, 2200);
  });
})();
