/* Inicio: avisa quando a secao esta ativa (fnr:homeactive) e alimenta a
   saida das camadas no scroll (--fnr-exit). Os videos ficam no modulo
   "OBJETOS FLUTUANTES". */
(function () {
  'use strict';

  var root = document.documentElement;
  var home = document.getElementById('home');
  if (!home) return;

  var inView  = true;
  var active  = true;
  var exitRaf = 0, lastP = -1;
  var reduceMq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
  var scroller = document.querySelector('.flpnr_tm_all_wrap .rightpart_in');

  window.__fnrHomeActive = true;
  root.classList.add('fnr-home-active');

  function setActive(on) {
    if (on === active) return;
    active = on;
    window.__fnrHomeActive = on;
    root.classList.toggle('fnr-home-active', on);
    try { window.dispatchEvent(new CustomEvent('fnr:homeactive', { detail: { on: on } })); } catch (e) {}
  }

  var FR = window.__fnrFrame || { queue: function (k, f) { requestAnimationFrame(function () { var w = f(); if (w) { w(); } }); }, defer: function (f) { f(); } };
  function updateExit() {                 /* leitura; a escrita volta como funcao */
    exitRaf = 0;
    if (!inView || window.__fnrLite || (reduceMq && reduceMq.matches)) return null;
    var r  = home.getBoundingClientRect();
    var vh = window.innerHeight || root.clientHeight || 1;
    var span = Math.max(1, Math.min(r.height, vh));
    var p = Math.min(1, Math.max(0, -r.top / span));
    p = Math.round(p * 1000) / 1000;
    if (p === lastP) return null;
    lastP = p;
    return function () { home.style.setProperty('--fnr-exit', p); };
  }
  function queueExit() { if (!exitRaf) { exitRaf = 1; FR.queue('exit', updateExit); } }

  function onScroll(e) {
    if (!inView) return;
    var t = e.target;
    if (t !== scroller && t !== document && t !== root && t !== document.body) return;
    queueExit();
  }

  if (!('IntersectionObserver' in window)) return;

  new IntersectionObserver(function (entries) {
    inView = entries[entries.length - 1].isIntersecting;
    if (inView) queueExit();
  }, { root: null, threshold: 0 }).observe(home);

  new IntersectionObserver(function (entries) {
    setActive(entries[entries.length - 1].isIntersecting);
  }, { root: null, rootMargin: '-40% 0px -40% 0px', threshold: 0 }).observe(home);

  document.addEventListener('scroll', onScroll, { capture: true, passive: true });
  window.addEventListener('resize', queueExit);
  window.addEventListener('fnr:lite', function (e) {
    if (e.detail && !e.detail.on) queueExit();
  });
})();
