/* ======================================================================
   FNR · OBJETOS FLUTUANTES (Inicio e 2a navegacao)
   Cada .fnr-floater tem uma imagem (repouso) e um video (vivo):
   - o video so carrega e toca com o objeto perto da tela, a aba visivel
     e o modo energia desligado; ate la aparece a imagem
   - no celular o video pausa durante a rolagem e volta quando ela para
   - longe da tela o video e descarregado (libera memoria e decodificador)
   Inicio: flutuacao + parallax do mouse (computador)
   2a navegacao: cada objeto acompanha a rolagem do seu par de paginas
   ====================================================================== */
(function () {
  "use strict";
  if (window.__fnrFloaters) return;
  window.__fnrFloaters = true;

  var root = document.documentElement;
  var els = [].slice.call(document.querySelectorAll(".fnr-floater"));
  if (!els.length) return;

  var touch = !!(window.matchMedia && matchMedia("(hover:none) and (pointer:coarse)").matches);
  var reduce = !!(window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches);
  var hasIO = "IntersectionObserver" in window;
  var FR = window.__fnrFrame || { queue: function (k, f) { requestAnimationFrame(function () { var w = f(); if (w) w(); }); } };
  var SOURCES = [["data-mp4", 'video/mp4; codecs="hvc1"'], ["data-webm", "video/webm"]];

  function lite() { return !!window.__fnrLite || root.classList.contains("fnr-lite"); }

  var all = els.map(function (el) {
    var f = {
      el: el,
      vid: el.querySelector(".fnr-floater-vid"),
      home: !el.classList.contains("fnr-f2"),
      near: !hasIO,
      inView: !hasIO,
      depth: parseFloat(el.getAttribute("data-depth")) || 0,
      scale: parseFloat(el.getAttribute("data-scale")) || 1,
      from: document.getElementById(el.getAttribute("data-from") || ""),
      to: document.getElementById(el.getAttribute("data-to") || ""),
      side: el.classList.contains("is-right") ? 1 : -1
    };
    if (f.vid) {
      f.vid.muted = true;
      f.vid.addEventListener("playing", function () { el.classList.add("is-live"); });
    }
    return f;
  });
  var homeF = all.filter(function (f) { return f.home; });
  var pageF = all.filter(function (f) { return !f.home && f.from && f.to; });

  /* ---------- video x imagem ---------- */
  var scrolling = false, scrollT = 0;
  function load(f) {
    var v = f.vid;
    if (!v || v.firstChild) return;
    SOURCES.forEach(function (s) {
      var url = v.getAttribute(s[0]);
      if (!url) return;
      var src = document.createElement("source");
      src.src = url;
      src.type = s[1];
      v.appendChild(src);
    });
    v.preload = "auto";
    try { v.load(); } catch (e) {}
  }
  function unload(f) {
    var v = f.vid;
    f.el.classList.remove("is-live");
    if (!v || !v.firstChild) return;
    try { v.pause(); } catch (e) {}
    while (v.firstChild) v.removeChild(v.firstChild);
    v.removeAttribute("src");
    try { v.load(); } catch (e) {}
  }
  function sync(f) {
    if (!f.vid) return;
    if (!f.near || lite() || document.hidden) { unload(f); return; }
    load(f);
    var v = f.vid;
    if (f.inView && !(touch && scrolling)) {
      if (v.paused) { var p = v.play(); if (p && p.catch) p.catch(function () {}); }
    } else if (!v.paused) {
      try { v.pause(); } catch (e) {}
    }
  }
  function syncAll() { all.forEach(sync); }

  /* "perto" = ate meia tela de distancia; "na tela" = qualquer parte visivel */
  function observe(targets, f, key, margin) {
    var state = targets.map(function () { return false; });
    var io = new IntersectionObserver(function (es) {
      es.forEach(function (e) { state[targets.indexOf(e.target)] = e.isIntersecting; });
      var on = state.indexOf(true) > -1;
      if (on === f[key]) return;
      f[key] = on;
      sync(f);
      if (!f.home) queuePlace();
    }, { rootMargin: margin });
    targets.forEach(function (t) { io.observe(t); });
  }
  if (hasIO) {
    homeF.forEach(function (f) {
      observe([f.el], f, "near", "50% 0px");
      observe([f.el], f, "inView", "0px");
    });
    pageF.forEach(function (f) {
      observe([f.from, f.to], f, "near", "100% 0px");
      observe([f.from, f.to], f, "inView", "60% 0px");
    });
  }

  /* ---------- 2a navegacao: acompanha a rolagem do par de paginas ---------- */
  var placeQueued = false;
  function queuePlace() {
    if (placeQueued || !pageF.length) return;
    placeQueued = true;
    FR.queue("floaters2", place);
  }
  /* cada objeto entra por baixo da tela, sobe mais devagar que o conteudo e sai por cima.
     A faixa de cada um avanca LEAD telas sobre as paginas vizinhas, por isso na troca
     de par os dois objetos aparecem juntos (um saindo, outro entrando). */
  var LEAD = 0.6;
  var box = document.getElementById("fnr-floaters2") || root;
  if (box !== root) document.body.insertBefore(box, document.body.firstChild); /* sticky precisa estar no topo */
  function place() {                         /* leitura de layout; devolve a escrita */
    placeQueued = false;
    var vh = window.innerHeight || 1, out = [];
    var bt = box.getBoundingClientRect();    /* camada passa da tela; centro dela em px na tela */
    var base = bt.top + (bt.height || vh) / 2;
    pageF.forEach(function (f) {
      if (!f.near) { if (f.shown) out.push([f, -1]); return; }
      var top = f.from.getBoundingClientRect().top - vh * LEAD;
      var bottom = f.to.getBoundingClientRect().bottom + vh * LEAD;
      var p = (vh - top) / ((bottom - top) + vh);
      if (p <= 0 || p >= 1) { if (f.shown) out.push([f, -1]); return; }
      if (!f.h) f.h = f.el.offsetHeight;
      out.push([f, p, f.h]);
    });
    return function () {
      out.forEach(function (o) {
        var f = o[0], p = o[1];
        if (p < 0) { f.el.classList.remove("is-on"); f.shown = false; return; }
        var off = vh / 2 + o[2] / 2 + 80;            /* centro fora da tela, embaixo e em cima */
        var y = vh / 2 - base + (reduce ? 0 : off * (1 - 2 * p));
        var x = reduce ? 0 : (p - 0.5) * -40 * f.side; /* deriva leve para o centro */
        var r = reduce ? 0 : (p - 0.5) * 10 * f.side;
        var s = reduce ? 1 : 0.94 + 0.12 * Math.sin(p * Math.PI);
        f.el.style.transform = "translate3d(" + x.toFixed(1) + "px," + y.toFixed(1) + "px,0) rotate(" + r.toFixed(2) + "deg) scale(" + s.toFixed(3) + ")";
        if (!f.shown) { f.el.classList.add("is-on"); f.shown = true; }
      });
    };
  }

  /* ---------- Inicio: flutuacao + parallax do mouse ---------- */
  var tx = 0, ty = 0, cx = 0, cy = 0, raf = 0, offX = 0, offY = 0;
  var homeOn = window.__fnrHomeActive !== false;
  function offsets() {
    var m = window.innerWidth <= 768;
    offX = m ? -25 : 0;
    offY = m ? -150 : 0;
  }
  function pose(frozen) {
    if (!frozen) { cx += (tx - cx) * 0.08; cy += (ty - cy) * 0.08; }
    var now = Date.now();
    homeF.forEach(function (f, i) {
      var range = 6 + i * 4, x, y, rot;
      if (frozen) {
        x = offX;
        y = offY - range / 2;
        rot = 0.5;
      } else {
        var t = now * (0.0015 + i * 0.0005) + f.depth * 10;
        x = -cx * f.depth + offX;
        y = -cy * f.depth + offY + Math.sin(t) * range / 2 - range / 2;
        rot = Math.sin(t) * 0.5 + 0.5;
      }
      f.el.style.transform = "translate(" + x + "px," + y + "px) rotate(" + rot + "deg) scale(" + f.scale + ")";
    });
  }
  function frame() {
    raf = 0;
    if (!homeOn || lite() || reduce) return;
    pose(false);
    raf = requestAnimationFrame(frame);
  }
  function startHome() {
    if (!homeF.length) return;
    if (lite() || reduce) {
      if (raf) { cancelAnimationFrame(raf); raf = 0; }
      tx = ty = cx = cy = 0;
      pose(true);
      return;
    }
    if (homeOn && !raf) raf = requestAnimationFrame(frame);
  }
  offsets();
  if (!touch) {
    document.addEventListener("mousemove", function (e) {
      tx = e.clientX - window.innerWidth / 2;
      ty = e.clientY - window.innerHeight / 2;
    }, { passive: true });
  }

  /* ---------- eventos ---------- */
  document.addEventListener("scroll", function () {
    queuePlace();
    if (!touch) return;
    if (!scrolling) { scrolling = true; syncAll(); }
    clearTimeout(scrollT);
    scrollT = setTimeout(function () { scrolling = false; syncAll(); }, 220);
  }, { passive: true, capture: true });
  window.addEventListener("resize", function () {
    pageF.forEach(function (f) { f.h = 0; });
    offsets();
    if (lite() || reduce) pose(true);
    queuePlace();
  });
  window.addEventListener("op:mounted", queuePlace);
  window.addEventListener("op:stage", queuePlace);
  document.addEventListener("visibilitychange", syncAll);
  window.addEventListener("fnr:homeactive", function (e) {
    homeOn = !(e && e.detail && e.detail.on === false);
    if (!homeOn && raf) { cancelAnimationFrame(raf); raf = 0; }
    else startHome();
  });
  window.addEventListener("fnr:lite", function () { startHome(); syncAll(); });

  startHome();
  syncAll();
  queuePlace();
})();
