(function () {
  'use strict';

  var AUDIO_URL      = 'https://files.catbox.moe/16flog.mp3';
  var LAYER_SELECTOR = '#fnr-speaker-hotspot';
  var FADE_IN_MS     = 1200;
  var FADE_OUT_MS    = 1500;

  var cursor     = document.getElementById('fnr-sound-cursor');
  var tooltip    = document.getElementById('fnr-sound-tooltip');
  var floatIcon  = document.getElementById('fnr-float-icon');
  var audio      = new Audio();
  var isOver     = false;
  var isPlaying  = false;
  var fadeTimer  = null;

  audio.src     = AUDIO_URL;
  audio.loop    = false;
  audio.volume  = 0;
  audio.preload = 'auto';

  var isTouchDevice = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0);

  function updateFloatIconVisibility() {
    if (!floatIcon || !isTouchDevice) return;
    var homeSection = document.getElementById('home');
    if (!homeSection) return;
    var cl = homeSection.classList;
    var isHomeActive = cl.contains('animated') && !cl.contains('hidden') && window.__fnrHomeActive !== false;  
    floatIcon.classList.toggle('fnr-show', isHomeActive);
    if (!isHomeActive && isPlaying) {
      audio.pause();
      isPlaying = false;
      floatIcon.classList.remove('playing');
      if (tooltip) tooltip.textContent = '\u25B6 clique para tocar';
    }
  }

  function observePageChanges() {
    var sections = document.querySelectorAll('.flpnr_tm_section');
    if (!sections.length) { setTimeout(observePageChanges, 400); return; }
    var observer = new MutationObserver(updateFloatIconVisibility);
    sections.forEach(function(sec) {
      observer.observe(sec, { attributes: true, attributeFilter: ['class'] });
    });
    updateFloatIconVisibility();
    window.addEventListener('fnr:homeactive', updateFloatIconVisibility);
  }

  function fadeTo(targetVol, durationMs, onDone) {
    if (fadeTimer) clearInterval(fadeTimer);
    var steps    = 30;
    var interval = durationMs / steps;
    var startVol = audio.volume;
    var delta    = (targetVol - startVol) / steps;
    var step     = 0;
    fadeTimer = setInterval(function () {
      step++;
      audio.volume = Math.min(1, Math.max(0, startVol + delta * step));
      if (step >= steps) {
        clearInterval(fadeTimer);
        fadeTimer = null;
        if (onDone) onDone();
      }
    }, interval);
  }

  function playWithFade() {
    audio.currentTime = 0;
    audio.volume = 0;
    var p = audio.play();
    isPlaying = true;
    if (cursor)    cursor.classList.add('playing');
    if (floatIcon) floatIcon.classList.add('playing');
    if (tooltip)   tooltip.textContent = '\u23F8 pausar';
    if (p !== undefined) {
      p.then(function () {
        if (isTouchDevice) {
          audio.volume = 1;
        } else {
          fadeTo(1, FADE_IN_MS);
        }
      }).catch(function (e) {
        isPlaying = false;
        if (cursor)    cursor.classList.remove('playing');
        if (floatIcon) floatIcon.classList.remove('playing');
        if (tooltip)   tooltip.textContent = '\u25B6 clique para tocar';
        console.warn('[FNR Audio]', e.message);
      });
    } else {
      if (isTouchDevice) {
        audio.volume = 1;
      } else {
        fadeTo(1, FADE_IN_MS);
      }
    }
  }

  function pauseWithFade() {
    if (isTouchDevice) {
      audio.pause();
      isPlaying = false;
      if (cursor)    cursor.classList.remove('playing');
      if (floatIcon) floatIcon.classList.remove('playing');
      if (tooltip)   tooltip.textContent = '\u25B6 clique para tocar';
    } else {
      fadeTo(0, FADE_OUT_MS, function () {
        audio.pause();
        isPlaying = false;
        if (cursor)    cursor.classList.remove('playing');
        if (floatIcon) floatIcon.classList.remove('playing');
        if (tooltip)   tooltip.textContent = '\u25B6 clique para tocar';
      });
    }
  }

  function moveCursor(x, y) {
    if (!cursor || !tooltip) return;
    cursor.style.left  = x + 'px';
    cursor.style.top   = y + 'px';
    tooltip.style.left = x + 'px';
    tooltip.style.top  = y + 'px';
  }

  if (floatIcon) {
    floatIcon.addEventListener('touchend', function (e) {
      e.preventDefault();
      e.stopPropagation();
      if (isPlaying) pauseWithFade();
      else playWithFade();
    });
    floatIcon.addEventListener('click', function () {
      if (isPlaying) pauseWithFade();
      else playWithFade();
    });
  }

  document.addEventListener('mousemove', function (e) {
    if (!isOver) return;
    moveCursor(e.clientX, e.clientY);
  });

  function init() {
    if (!isTouchDevice) {
      var homeEl = document.getElementById('home');
      if (!homeEl) { setTimeout(init, 300); return; }

homeEl.addEventListener('mouseenter', function (e) {
  isOver = true;
  moveCursor(e.clientX, e.clientY);
  if (cursor)  cursor.classList.add('fnr-show');
  if (tooltip) tooltip.classList.add('fnr-show');
});
homeEl.addEventListener('mouseleave', function () {
  isOver = false;
  if (cursor)  cursor.classList.remove('fnr-show');
  if (tooltip) tooltip.classList.remove('fnr-show');
  if (isPlaying) pauseWithFade();
});
homeEl.addEventListener('click', function () {
  if (isPlaying) pauseWithFade();
  else playWithFade();
});

var excludeSelectors = ['#profile-container', '.flpnr_tm_home .details'];
excludeSelectors.forEach(function (sel) {
  var el = document.querySelector(sel);
  if (!el) return;
  el.addEventListener('mouseenter', function () {
    isOver = false;
    if (cursor)  cursor.classList.remove('fnr-show');
    if (tooltip) tooltip.classList.remove('fnr-show');
  });
  el.addEventListener('mouseleave', function (e) {
    isOver = true;
    moveCursor(e.clientX, e.clientY);
    if (cursor)  cursor.classList.add('fnr-show');
    if (tooltip) tooltip.classList.add('fnr-show');
  });
  el.addEventListener('click', function (e) {
    e.stopPropagation();
  });
});
    }



    audio.addEventListener('ended', function () {
      isPlaying = false;
      if (cursor)    cursor.classList.remove('playing');
      if (floatIcon) floatIcon.classList.remove('playing');
      if (tooltip)   tooltip.textContent = '\u25B6 clique para tocar';
    });

    if (isTouchDevice) observePageChanges();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
