(function() {
    var loading = false;
    var nextUrl = '';

    function getNextPage() {
        if (loading) return;

        var nextLink = document.querySelector('a.blog-pager-older-link');
        if (!nextLink) return;

        nextUrl = nextLink.href;

        if ((window.innerHeight + window.scrollY) >= (document.body.offsetHeight - 400)) {
            loading = true;

            var loadingDiv = document.createElement('div');
            loadingDiv.id = 'infinite-scroll-loading';
            loadingDiv.innerHTML = '<p style="text-align:center; padding:20px;">Carregando mais postagens...</p>';
            var mainContent = document.querySelector('#main, .main, #Blog1');
            if(mainContent) mainContent.appendChild(loadingDiv);

            var pager = document.querySelector('#blog-pager');
            if (pager) pager.style.display = 'none';

            var xhr = new XMLHttpRequest();
            xhr.open('GET', nextUrl, true);
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4 && xhr.status === 200) {
                    var parser = new DOMParser();
                    var doc = parser.parseFromString(xhr.responseText, 'text/html');

                    var newPosts = doc.querySelectorAll('.date-outer, .post-outer, .blog-post');
                    var container = document.querySelector('.blog-posts, #Blog1');

                    if (newPosts.length > 0 && container) {
                        newPosts.forEach(function(post) {
                            if(!post.querySelector('.blog-posts')) {
                                container.appendChild(post);
                            }
                        });

                        var newNextLink = doc.querySelector('a.blog-pager-older-link');
                        if (newNextLink) {
                            nextLink.href = newNextLink.href;
                            loading = false;
                        } else {
                            if(loadingDiv) loadingDiv.innerHTML = '<p style="text-align:center; padding:20px;">Fim das postagens.</p>';
                            loading = true;
                        }
                    }
                    if(loadingDiv && nextUrl && !loading) loadingDiv.remove();
                }
            };
            xhr.send();
        }
    }

    var nextPageTick = false;
    function getNextPageRaf() {
        if (nextPageTick) return;
        nextPageTick = true;
        requestAnimationFrame(function () { nextPageTick = false; getNextPage(); });
    }
    window.addEventListener('scroll', getNextPageRaf, { passive: true });
    window.addEventListener('resize', getNextPageRaf, { passive: true });
})();
