/* Cartoes da home (Projetos e Conceitos, 3D e Motion Design, Identidades Visuais):
   inclinacao 3D com o mouse e troca automatica dos videos.
   Modo energia: sem inclinacao; a troca continua (com as imagens de capaa). */
(function () {
  var root = document.documentElement;
  function lite() { return !!window.__fnrLite || root.classList.contains("fnr-lite"); }

  function initTilt(wrapId, cardId) {
    var wrap = document.getElementById(wrapId), card = document.getElementById(cardId);
    if (!wrap || !card) return;
    var tRX = 0, tRY = 0, cRX = 0, cRY = 0, raf = 0;
    function anim() {
      raf = 0;
      cRX += (tRX - cRX) * 0.1;
      cRY += (tRY - cRY) * 0.1;
      if (!tRX && !tRY && Math.abs(cRX) < 0.05 && Math.abs(cRY) < 0.05) { card.style.transform = ""; return; }
      card.style.transform = "rotateX(" + cRX + "deg) rotateY(" + cRY + "deg) scale(1.02)";
      raf = requestAnimationFrame(anim);
    }
wrap.addEventListener("mousemove", function (e) {
  if (lite() || window.innerWidth <= 1200) return;
      var r = wrap.getBoundingClientRect();
      tRY = ((e.clientX - (r.left + r.width / 2)) / (r.width / 2)) * 11;
      tRX = -((e.clientY - (r.top + r.height / 2)) / (r.height / 2)) * 7;
      if (!raf) raf = requestAnimationFrame(anim);
    });
    wrap.addEventListener("mouseleave", function () {
      tRX = 0; tRY = 0;
      if (!raf) raf = requestAnimationFrame(anim);
    });
