      if (!lite()) return;
      tRX = tRY = cRX = cRY = 0;
      if (raf) { cancelAnimationFrame(raf); raf = 0; }
      card.style.transform = "";
    });
  }

  if (!/iPhone|iPad|iPod|Android/i.test(navigator.userAgent)) {
    initTilt("fnr_wrap_1", "fnr_card_1");
    initTilt("fnr_wrap_2", "fnr_card_2");
    initTilt("fnr_wrap_3", "fnr_card_3");
  }

  function cycleFrames(stripId, ms) {
    var strip = document.getElementById(stripId);
    if (!strip) return;
    var imgs = strip.querySelectorAll("img, video"), cur = 0;
    setInterval(function () {
      if (document.hidden) return;
      strip.classList.remove("fnr_flash");
      void strip.offsetWidth;
      strip.classList.add("fnr_flash");
      setTimeout(function () {
        imgs[cur].classList.remove("fnr_active");
        cur = (cur + 1) % imgs.length;
        imgs[cur].classList.add("fnr_active");
      }, 200);
    }, ms);
  }

  cycleFrames("fnr_strip_1", 3200);
  cycleFrames("fnr_strip_2", 5000);
  cycleFrames("fnr_strip_3", 5015);
})();
