(function(){
  var root=document.documentElement, done=false, t0=Date.now(), loaded=document.readyState==='complete';
  window.addEventListener('load',function(){loaded=true;});

  function homeVisible(){
    var h=document.getElementById('home'); if(!h) return false;
    if(root.classList.contains('spa-booting')) return false;
    var cs=getComputedStyle(h);
    return cs.visibility==='visible' && parseFloat(cs.opacity)>0.9 && h.getBoundingClientRect().width>0;
  }
  function preloaderGone(){
    var p=document.getElementById('preloader');
    return !p || p.classList.contains('preloaded');
  }
  function bgUrl(w){
    var el=w.querySelector('.avatar .image'); if(!el) return null;
    var m=(getComputedStyle(el).backgroundImage||'').match(/url\(["']?(.*?)["']?\)/);
    return m?m[1]:null;
  }
  var started=false;
  function calm(cb){
    var n=0,last=performance.now(),limit=last+2500;
    (function f(t){
      n=(t-last<40)?n+1:0; last=t;
      if(n>=5||t>limit) cb(); else requestAnimationFrame(f);
    })(last);
  }
  function fire(w){
    if(done) return; done=true;
    w.classList.remove('fnr-story-play');
    void w.offsetWidth;                                   
    calm(function(){
      w.classList.add('fnr-story-play');
      setTimeout(function(){root.classList.remove('fnr-story-ready');},3200);
    });
  }
  function check(){
    if(done) return true;
    if(started) return false;
    var w=document.getElementById('main-photo-container'); if(!w) return false;
    if(!root.classList.contains('fnr-story-ready')){done=true;return true;}  
    if(!homeVisible()) return false;
    var u=bgUrl(w);
    if(!u && Date.now()-t0<6000) return false;            
    started=true;
    if(u){
      var img=new Image(); img.src=u;
      var go=function(){fire(w);};
      (img.decode?img.decode():Promise.reject()).then(go,go);
      setTimeout(go,1500);                                
    } else fire(w);
    return true;
  }
  var iv=setInterval(function(){ if(check()) clearInterval(iv); },150);

  window.fnrStoryReplay=function(){
    var w=document.getElementById('main-photo-container'); if(!w) return;
    w.classList.remove('fnr-story-play'); void w.offsetWidth; done=false; started=true;
    root.classList.add('fnr-story-ready'); fire(w);
  };
})();
