(function(){
var tm;
function fixLists(){
var L=document.querySelectorAll('ul:not([role]),ol:not([role])'),i,j,c,b,n;
for(i=0;i<L.length;i++){c=L[i].children;b=false;for(j=0;j<c.length;j++){n=c[j].tagName;if(n!=='LI'&&n!=='SCRIPT'&&n!=='TEMPLATE'){b=true;break;}}if(b)L[i].setAttribute('role','presentation');}
var I=document.querySelectorAll('li:not([role])'),p;
for(i=0;i<I.length;i++){p=I[i].parentElement;if(!p||!/^(UL|OL|MENU)$/.test(p.tagName)||p.getAttribute('role')==='presentation')I[i].setAttribute('role','presentation');}
}
function fixHeadings(){
var H=document.querySelectorAll('h1,h2,h3,h4,h5,h6'),prev=0,i,h,l,a;
for(i=0;i<H.length;i++){h=H[i];if(!h.getClientRects().length||getComputedStyle(h).visibility==='hidden')continue;
l=+h.tagName.charAt(1);a=parseInt(h.getAttribute('aria-level'),10);if(a>0)l=a;
if(prev&&l>prev+1){l=prev+1;h.setAttribute('aria-level',String(l));}
prev=l;}
}
function fixImgs(){
var I=document.querySelectorAll('article img[src*="googleusercontent.com/img/b/"]'),i,m,im;
for(i=0;i<I.length;i++){im=I[i];if(im.complete&&im.naturalWidth)continue;
m=/^(https:\/\/blogger\.googleusercontent\.com\/img\/b\/.+?)\/s1600\/([^\/?#]+\.jpe?g)$/i.exec(im.getAttribute('src'));
if(m)im.setAttribute('src',m[1]+'/s1000-rw/'+m[2]);}
}
function run(){try{fixLists();fixHeadings();fixImgs();}catch(e){}}
function later(){clearTimeout(tm);tm=setTimeout(run,600);}
document.addEventListener('DOMContentLoaded',run);
window.addEventListener('load',function(){run();setTimeout(run,1500);setTimeout(run,4000);});
window.addEventListener('hashchange',later);
window.addEventListener('popstate',later);
document.addEventListener('click',later,true);
})();
