  a.addEventListener("click", function (e) {
    var colored = a.classList.contains("is-colored");
    for (var k = 0; k < anchors.length; k++) if (anchors[k] !== a) anchors[k].classList.remove("is-colored");
    if (TAP && !colored) { e.preventDefault(); a.classList.add("is-colored"); return; }
    a.classList.add("is-colored");
  });
  anchors.push(a);
}
function init() {
  var list = document.querySelectorAll(SEL);
  for (var i = 0; i < list.length; i++) setup(list[i]);
}
document.addEventListener("click", function (e) {
  var t = e.target;
  if (t && t.closest && t.closest(SEL)) return;
  for (var i = 0; i < anchors.length; i++) anchors[i].classList.remove("is-colored");
}, true);
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
else init();
window.addEventListener("load", function () { init(); setTimeout(init, 1500); });
})();
