function touchMode() { return window.matchMedia(MQ).matches; }
function getTip() {
  if (!tip || !tip.isConnected) {
    tip = document.querySelector(".flpnr_tm_portfolio_titles");
    if (!tip) { tip = document.createElement("div"); tip.className = "flpnr_tm_portfolio_titles"; document.body.appendChild(tip); }
  }
  return tip;
}
function info(el) {
  if (el.classList.contains("nn-thumb")) {
    var l = el.querySelector(".nn-label");
    var lb = l ? l.querySelector("b") : null, li = l ? l.querySelector("i") : null;
    return { t: lb ? lb.textContent.trim() : (l ? l.textContent.trim() : ""), s: li ? li.textContent.trim() : "" };
  }
  var b = el.querySelector(".fnr-pj-cap b"), i = el.querySelector(".fnr-pj-cap i");
  return { t: b ? b.textContent.trim() : "", s: i ? i.textContent.trim() : "" };
