function show(el, e) {
  var d = info(el);
  if (!d.t) return;
  var t = getTip();
  t.textContent = "";
  t.appendChild(document.createTextNode(d.t));
  if (d.s) {
    var sp = document.createElement("span");
    sp.className = "work__cat";
    sp.textContent = d.s.length > 35 ? d.s.substring(0, 35) + "..." : d.s;
    t.appendChild(sp);
  }
  t.classList.add("visible");
