(function () {
"use strict";
if (window.__fnrPdfTilt) return;
window.__fnrPdfTilt = true;
if (!window.matchMedia || !window.matchMedia("(hover: hover) and (pointer: fine)").matches) return;
if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

var SEL = ".nn-thumb", MAX_Y = 11, MAX_X = 7, SCALE = 1.02;
var states = new Map(), cur = null, raf = 0;

function geo(el) {
  var r = el.getBoundingClientRect();
  return { cx: r.left + r.width / 2, cy: r.top + r.height / 2, hw: el.offsetWidth / 2, hh: el.offsetHeight / 2 };
}
function inside(el, e) {
  var g = geo(el);
  return Math.abs(e.clientX - g.cx) <= g.hw && Math.abs(e.clientY - g.cy) <= g.hh;
}
function clamp(v) { return v < -1 ? -1 : (v > 1 ? 1 : v); }
function loop() {
  raf = 0;
  var again = false;
  states.forEach(function (s, el) {
    s.rx += (s.tx - s.rx) * 0.1;
    s.ry += (s.ty - s.ry) * 0.1;
    s.sc += (s.ts - s.sc) * 0.1;
    if (!s.hover && Math.abs(s.rx) < 0.05 && Math.abs(s.ry) < 0.05 && s.sc < 1.0005) {
      el.style.transform = "";
      el.classList.remove("fnr-tilt");
      states.delete(el);
      return;
    }
    el.style.transform = "perspective(900px) rotateX(" + s.rx.toFixed(3) + "deg) rotateY(" + s.ry.toFixed(3) + "deg) scale(" + s.sc.toFixed(4) + ")";
    again = true;
  });
  if (again) raf = requestAnimationFrame(loop);
}
function kick() { if (!raf) raf = requestAnimationFrame(loop); }
function stateOf(el) {
  var s = states.get(el);
  if (!s) { s = { rx: 0, ry: 0, sc: 1, tx: 0, ty: 0, ts: 1, hover: false }; states.set(el, s); }
  return s;
}
function leave(el) {
  if (!el) return;
  var s = states.get(el);
  if (!s) return;
  s.hover = false; s.tx = 0; s.ty = 0; s.ts = 1;
  kick();
}
document.addEventListener("mousemove", function (e) {
  var el = (cur && inside(cur, e)) ? cur : (e.target && e.target.closest ? e.target.closest(SEL) : null);
  if (el !== cur) { leave(cur); cur = el; }
  if (!el) return;
  var g = geo(el), s = stateOf(el);
  s.hover = true; s.ts = SCALE;
  s.ty = clamp((e.clientX - g.cx) / g.hw) * MAX_Y;
  s.tx = -clamp((e.clientY - g.cy) / g.hh) * MAX_X;
  el.classList.add("fnr-tilt");
  kick();
}, { passive: true });
document.documentElement.addEventListener("mouseleave", function () { leave(cur); cur = null; });
window.addEventListener("blur", function () { leave(cur); cur = null; });
})();
