(function () {
  var parts = location.pathname.split('/');
  var onLabel = parts[1] === 'search' && parts[2] === 'label';
  var cur = '';
  if (onLabel) { try { cur = decodeURIComponent(parts[3] || '').replace(/\+/g, ' '); } catch (e) {} }

  var mine = {};
  [].forEach.call(document.querySelectorAll('.fnr-post-tags a, .post-labels a.label-link'), function (a) {
    var n = (a.textContent || '').trim(); if (n) mine[n] = 1;
  });
  if (cur) mine[cur] = 1;

  function load(cb) {
    fetch('/feeds/posts/summary?alt=json&max-results=0')
      .then(function (r) { return r.json(); })
      .then(function (j) {
        var cats = (j.feed && j.feed.category) || [], out = [];
        cats.forEach(function (c) { if (c.term) out.push(c.term); });
        cb(out.length ? out : Object.keys(mine));
      })
      .catch(function () { cb(Object.keys(mine)); });
  }

  function fill(ul, names, desk) {
    if (ul.querySelector('.fnr-tag-li')) return;
    names.forEach(function (n, i) {
      var li = document.createElement('li'), a = document.createElement('a'), sp = document.createElement('span');
      li.className = 'fnr-tag-li' + (mine[n] ? ' active' : '');
      a.href = '/search/label/' + encodeURIComponent(n);
      a.title = n; sp.textContent = n; a.appendChild(sp);
      if (desk) {   /* mesma estrutura da linha do tempo dos outros menus */
        var pc = document.createElement('span'), nd = document.createElement('span');
        pc.className = 'tl-pct'; pc.setAttribute('aria-hidden', 'true');
        nd.className = 'tl-node'; nd.setAttribute('aria-hidden', 'true');
        nd.innerHTML = '<i class="tl-up"></i><i class="tl-dn"></i><b class="tl-dot"></b>';
        li.className += ' tl-li';
        li.style.setProperty('--tl-i', i + 1);
        li.appendChild(pc); li.appendChild(nd);
      }
      li.appendChild(a);
      ul.appendChild(li);
    });
  }

  function run() {
    load(function (names) {
      names = names.slice().sort(function (a, b) { return a.localeCompare(b, 'pt'); });
      var d = document.querySelector('.leftpart .menu ul.transition_link');
      if (d) fill(d, names, true);
      var m = document.querySelector('.flpnr_tm_mobile_menu .menu_list ul.transition_link');
      if (m) fill(m, names, false);
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { setTimeout(run, 0); });
  else setTimeout(run, 0);
})();
